export default {
 "replies": {
  "17x4dgsdcxk": "{\"title\":\"Oliver (eastern grey kangaroo joey) care log\",\"subtitle\":\"Thursday\",\"sections\":[{\"heading\":\"Summary\",\"text\":\"Oliver is feeding well, gaining weight and spending more time out of the pouch.\"},{\"heading\":\"Weight\",\"text\":\"2.31 kg this morning, up 40 g since Monday.\"},{\"heading\":\"Feeding\",\"items\":[\"Four bottle feeds of Wombaroo 0.7, 120 mL each.\",\"Took all feeds; the last one a bit slowly.\",\"Started picking at kangaroo grass.\"]},{\"heading\":\"Toileting\",\"text\":\"Toileted after every feed with stimulation. Normal pellets.\"},{\"heading\":\"Behaviour and condition\",\"text\":\"Spending more time out of the pouch and hopping around the room.\"},{\"heading\":\"Wounds and treatment\",\"text\":\"Small scrape on his tail from the pen door, cleaned with saline.\"},{\"heading\":\"To watch\",\"items\":[\"Small tail scrape from the pen door. Consider a vet check if it gets worse or doesn't heal.\"]}],\"due\":[{\"what\":\"Next weigh-in\",\"when\":\"Monday\"}],\"check\":[\"Has the pen door been made safe?\"]}",
  "1ogl7yq9l5f": "{\"title\":\"Rescue and intake record: adult female bare-nosed wombat\",\"subtitle\":\"Wildlife Victoria case 26-04417\",\"sections\":[{\"heading\":\"Register entry\",\"text\":\"\",\"items\":[\"Case number: Wildlife Victoria 26-04417\",\"Common name: Bare-nosed wombat\",\"Species code: Not recorded\",\"Date in: Not recorded\",\"Sex (M, F or U): F\",\"Age class: Adult\",\"Main injury: Graze on left shoulder; severe mange\",\"Cause: Hit by car\",\"Where found: Bass Highway near Kilcunda, the gravel pull-over on the south side of the highway, just east of the Kilcunda bridge\",\"Status: In care, vet booked\"]},{\"heading\":\"Rescue details\",\"text\":\"\",\"items\":[\"Rescued last night. A motorist called it in at about 9 pm, and the carer picked her up at 9.40 pm.\",\"Wildlife Victoria case number: 26-04417\",\"Came into care after being hit by a car on the Bass Highway near Kilcunda.\"]},{\"heading\":\"Where it was found\",\"text\":\"Bass Highway near Kilcunda: the gravel pull-over on the south side of the highway, just east of the Kilcunda bridge.\",\"items\":[]},{\"heading\":\"Animal\",\"text\":\"\",\"items\":[\"Species: Bare-nosed wombat\",\"Sex: Female\",\"Age: Adult\",\"Weight: About 24 kg\",\"Pouch empty\"]},{\"heading\":\"Condition on arrival\",\"text\":\"\",\"items\":[\"Severe mange over both flanks and back\",\"Crusting on both ears\",\"Graze on the left shoulder\",\"Walking okay, with no obvious fractures\",\"Alert and hissing\"]},{\"heading\":\"First aid and care given\",\"text\":\"\",\"items\":[\"Placed in the quiet pen with a hide box and water\"]},{\"heading\":\"Vet\",\"text\":\"Booked with the Wildlife Victoria travelling vet for tomorrow morning.\",\"items\":[]}],\"due\":[{\"what\":\"Wildlife Victoria travelling vet visit\",\"when\":\"Tomorrow morning\"}],\"check\":[\"What was the rescue date?\",\"What is the shelter case number?\"]}",
  "1evka698ir7": "{\"title\":\"Vet visit summary: Willow, juvenile female wombat\",\"subtitle\":\"Bunurong Wildlife Care, Inverloch\",\"sections\":[{\"heading\":\"Text to your vet\",\"text\":\"Bunurong Wildlife Care re Willow, juvenile female wombat, in care 5 weeks since her mum was hit on the Inverloch road. On the mange treatment you prescribed, last dose 10 days ago. Weight down from 6.2 to 6.0 kg over the past week, eating fewer pellets but still grazing, loose droppings for 2 days, scratching more again. Is the weight drop a worry, does she need another mange dose, and when can she go to the outdoor enclosure?\",\"items\":[]},{\"heading\":\"Animal\",\"text\":\"\",\"items\":[\"Species: common wombat (juvenile)\",\"Sex: female\",\"Name: Willow\",\"Current weight: 6.0 kg\"]},{\"heading\":\"Reason for visit\",\"text\":\"Weight loss, reduced pellet intake, loose droppings and increased scratching while on mange treatment. The carer is also seeking advice on further mange treatment and timing of the move to the outdoor enclosure.\",\"items\":[]},{\"heading\":\"History in care\",\"text\":\"Came into care five weeks ago after her mother was hit by a vehicle on the Inverloch road. Currently on mange treatment prescribed by the vet.\",\"items\":[]},{\"heading\":\"Recent observations\",\"text\":\"\",\"items\":[\"Weight: dropped from 6.2 kg to 6.0 kg over the last week\",\"Feeding: eating fewer pellets, still grazing\",\"Toileting: loose droppings for the past 2 days\",\"Skin and behaviour: scratching more again\"]},{\"heading\":\"Current medications and treatment\",\"text\":\"\",\"items\":[\"Mange treatment as prescribed by the vet; last dose given 10 days ago\"]},{\"heading\":\"Questions for the vet\",\"text\":\"\",\"items\":[\"Is the 0.2 kg weight loss over the past week a concern?\",\"Could the loose droppings and reduced pellet intake need treatment or investigation?\",\"Does the increased scratching mean she needs another mange dose now?\",\"When can she move to the outdoor enclosure?\"]},{\"heading\":\"What the carer needs back\",\"text\":\"\",\"items\":[\"Written dosing instructions if another mange dose is needed\",\"Advice on when she can move to the outdoor enclosure\"]}],\"due\":[],\"check\":[\"What is the mange treatment's name and dose?\",\"What was the exact rescue date?\",\"How often has the mange treatment been given?\",\"Any other problems or treatment since rescue?\"]}",
  "1fh60ca4b35": "{\"title\":\"Short-term care plan: juvenile common brushtail possum\",\"subtitle\":\"Found this evening in Wonthaggi\",\"sections\":[{\"heading\":\"Text to send\",\"text\":\"Hi Jenny, thanks for helping the young possum. Keep it in a box with air holes, lined with a towel and with the lid secured, in your dark, quiet laundry. Wrap a warm (not hot) hot water bottle in a towel and put it at one end so the possum can move away. Handle it as little as possible and keep pets and children away. Don't give food or water unless a vet or wildlife carer advises otherwise. A rescuer will collect it tomorrow around 8 am. Wash your hands after touching it. Call back if it gets cold, weak or floppy, or if you see blood.\"},{\"heading\":\"Right now\",\"items\":[\"Make sure the box has air holes, a towel lining and a secure lid.\",\"Keep the box in the laundry, where it is dark, quiet and warm.\",\"Handle the possum as little as possible.\",\"Keep pets and children away.\"]},{\"heading\":\"Basic first aid\",\"items\":[\"Fill the hot water bottle with warm, not hot, water. Wrap it in a towel and put it at one end of the box.\",\"Refill the bottle with warm water when it cools, including before bed and early in the morning.\",\"Cover the box with a light towel.\",\"Do not give food or water unless a vet, wildlife carer or Wildlife Victoria advises otherwise.\"]},{\"heading\":\"Getting it to a vet or shelter\",\"items\":[\"A rescuer will collect it tomorrow morning around 8.\",\"Keep the box closed and ready in the laundry.\",\"This is short-term care only, until the rescuer arrives.\"]},{\"heading\":\"Keep yourself safe\",\"items\":[\"Possums can scratch and bite. If you must handle it, wear gloves and long sleeves.\",\"Wash your hands after touching the possum or the box.\"]},{\"heading\":\"Call back straight away if\",\"items\":[\"It feels cold, goes floppy or can't hold its head up.\",\"Its breathing is noisy or difficult.\",\"You see blood or an injury.\",\"A dog or cat gets to it.\",\"Wildlife Victoria: 03 8400 7300 (24/7).\"]},{\"heading\":\"Where it was found\",\"text\":\"On the ground in the backyard in Wonthaggi, under the big gum near the back fence.\"}],\"due\":[{\"what\":\"Rescuer collects possum\",\"when\":\"Tomorrow morning around 8 am\"}],\"check\":[\"What is Jenny's street address?\",\"Is the possum warm or cold to touch?\",\"What is today's date?\"]}",
  "2d95fnhrtva": "{\"title\":\"Treating Wombat Mange in the Wild: Second Wildlife Ambulance Trailer and Burrow-Flap Kit\",\"subtitle\":\"Bass Coast Shire Community Grants, Environment Stream\",\"sections\":[{\"heading\":\"Project summary\",\"text\":\"We are seeking $8,500 for a second wildlife ambulance trailer, a portable wombat burrow-flap kit with treatment supplies, and a volunteer training day. This will let us treat mange in wombats where they live instead of bringing every affected wombat into care. The project will run from February to December next year.\",\"items\":[]},{\"heading\":\"About us\",\"text\":\"Bunurong Wildlife Care Inc is a registered charity and authorised wildlife shelter (Wildlife Shelter 15147751) based in Inverloch, Victoria. We rescue, rehabilitate and release native wildlife across Bass Coast and South Gippsland, supported by 18 trained volunteers.\",\"items\":[]},{\"heading\":\"The need\",\"text\":\"Last year we took in 214 animals. About a third of them were wombats, and 60 of those wombats had mange. At present we bring every wombat with mange into care for treatment. Treating mange in the wild is gentler on the wombats, and it frees space and volunteer time at the shelter.\",\"items\":[]},{\"heading\":\"What we will do\",\"items\":[\"Buy a second wildlife ambulance trailer to increase our rescue and transport capacity.\",\"Buy a portable wombat burrow-flap kit and treatment supplies so we can treat mange at the burrow.\",\"Run a volunteer training day so our team can use the burrow-flap kit safely and effectively.\",\"Monitor treated wombats with trail cameras to track their recovery.\"],\"text\":\"\"},{\"heading\":\"Budget\",\"items\":[\"Wildlife ambulance trailer: $5,200\",\"Burrow-flap kit and treatment supplies: $2,100\",\"Volunteer training day: $1,200\",\"Total requested: $8,500\"],\"text\":\"\"},{\"heading\":\"Timeline\",\"text\":\"The project will run from February to December next year.\",\"items\":[]},{\"heading\":\"Outcomes and how we will measure them\",\"items\":[\"Wombats with mange treated in the wild, measured by the number of wombats treated at their burrows.\",\"Wombats recovering from mange, measured by the recoveries we observe on trail cameras.\"],\"text\":\"\"},{\"heading\":\"Who benefits\",\"items\":[\"Wombats with mange, which can be treated without being removed from their burrows.\",\"Native wildlife across Bass Coast and South Gippsland, through greater rescue capacity from a second ambulance trailer.\",\"Our volunteers, through hands-on training in mange treatment in the wild.\"],\"text\":\"\"},{\"heading\":\"Partners and support\",\"text\":\"Wildlife Victoria and local vets already refer animals to us.\",\"items\":[]},{\"heading\":\"Why us\",\"text\":\"We are an authorised wildlife shelter with 18 trained volunteers and an established referral relationship with Wildlife Victoria and local vets. Last year we cared for 214 animals, including 60 wombats with mange, so we know the scale of the problem in our area and are well placed to treat it in the field.\",\"items\":[]}],\"due\":[{\"what\":\"Project start\",\"when\":\"February next year\"},{\"what\":\"Project end\",\"when\":\"December next year\"}],\"check\":[\"What is the grant application deadline?\",\"Which calendar year is \\\"next year\\\"?\",\"How many wombats do you expect to treat?\",\"Any recovery figures from past trail camera monitoring?\",\"Any letters of support from referrers?\"]}",
  "bcz5hijz7l": "{\"animal\":\"Adult female bare-nosed wombat\",\"species\":\"Common (bare-nosed) wombat (Vombatus ursinus)\",\"kind\":\"wildlife\",\"summary\":\"She was hit by a car on the Bass Highway near Kilcunda last night and has severe mange over her flanks, back and ears, plus a grazed left shoulder, but she is alert and walking well. The goal is to keep her calm, safe and comfortable overnight so the vet can assess her tomorrow morning and set her treatment plan.\",\"photo_findings\":[],\n\"medications\":[],\n\"plan\":[{\"when\":\"Tonight until the vet arrives\",\"tasks\":[\"Leave her undisturbed in the quiet pen and watch her only from outside the pen.\"]},{\"when\":\"Tomorrow morning (vet visit)\",\"tasks\":[\"Ask the vet to check her teats; if one is long, a joey may be near the find site, so call Wildlife Victoria on (03) 8400 7300 to arrange a search.\"]},{\"when\":\"After the vet visit\",\"tasks\":[\"Start any mange treatment, pain relief or wound care exactly as the vet prescribes.\"]}],\n\"housing\":[\"Keep her in the quiet, dimly lit pen with her hide box, away from people, pets and other wildlife.\",\"Keep her cool, as wombats do not sweat and overheat easily; adults never need temperatures above 25°C.\",\"Treat her as a mange case in strict quarantine: use separate equipment, service her last, and leave the pen clean and empty for at least three weeks after she leaves.\",\"Remove droppings every day, keep bedding straw free of cat faeces, and hot-wash and hot-dry all bedding, because mites survive up to 21 days.\"],\n\"feeding\":[\"Offer fresh grasses, ideally pulled with roots and dirt, plus grass hay, as her main food.\",\"Grass-based pellets can make up no more than a tenth of her daily food; never give cattle or chicken pellets, as some contain coccidiostats that can kill wombats.\",\"Avoid bread, cereal biscuits, muesli mixes and carrots, which cause gum infections and bloat or teach her to trust rabbit bait.\",\"Give fresh water in a heavy, shallow dish and change it every day.\"],\n\"activity\":[\"Handle her as little as possible, as she weighs about 24 kg, can bite and scratch, and her hard rump can crush hands against a wall.\",\"Wear gloves and covered clothing whenever you enter her pen, as people can catch mange and wombats can carry salmonella and ringworm.\",\"Wash your hands thoroughly every time you leave her pen.\"],\n\"care\":[\"Record her admission with case number 26-04417, date in, the cause (vehicle strike), her injuries and the exact find site (gravel pull-over, south side of the Bass Highway, just east of the Kilcunda bridge), adding GPS coordinates if you can.\",\"Record every treatment with the date, drug, dose, how often and the result, and keep records for three years.\"],\n\"daily_checks\":[\"Eating and drinking\",\"Droppings normal\",\"Shoulder graze clean\",\"Alert and moving well\",\"Pen cleaned\"],\n\"log_days\":2,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24000,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult wombat on a grass and hay diet, not a measured milk feed.\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Mange fully cleared with all scabs gone and fur regrowing\",\"Shoulder graze healed and no more medical care needed\",\"Walking, digging and eating grass normally\",\"Wary of people, as a wild wombat should be\"],\"target_weight\":\"About 24 kg or more in good body condition; I'm not certain of her ideal weight, so check with your vet\",\"how\":[\"Release within 24 hours of her being ready, avoiding hot or stormy weather.\",\"Release about an hour after dusk.\",\"Ideally place her at an unoccupied burrow entrance.\",\"Let her leave in her own time without chasing her.\"],\"where\":\"Release her where she was found near the Kilcunda bridge, or at the closest suitable spot within her home range (ideally within about 150 m) without crossing a boundary she would not normally cross.\"},\n\"escalate\":{\"vet\":[\"Not eating or drinking by the vet visit or at any point after\",\"The shoulder graze becomes swollen, smelly or oozing\",\"Diarrhoea, or no droppings for a day\",\"Limping or reluctance to walk\"],\"urgent\":[\"Collapse, wobbliness or unable to stand\",\"Laboured breathing, or blood from the nose or mouth\",\"Heat stress signs: red feet, saliva on her forelegs and chest, or lying on her back\",\"Flies laying eggs on her skin, or a rotting smell\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Wildlife Victoria travelling vet, tomorrow morning\",\"sources\":[\"vic-rehab-guidelines-wombats\",\"vic-cop-welfare-wildlife-rehabilitation\",\"vic-rehabilitator-authorisation-conditions\",\"vic-release-requirements\",\"vic-shelter-foster-carer-authorisation\",\"vic-authorisation-guide-first-aid\",\"vic-rehab-guidelines-part-a\",\"vic-mange-management\",\"au-sarcoptic-mange-treatment-sheet\",\"vic-wildlife-victoria-emergency-response\"]}",
  "qpdjzklu0m": "{\"animals\":[{\"patient\":{\"name\":\"\",\"species\":\"Bare-nosed wombat (Vombatus ursinus)\",\"breed\":\"\",\"sex\":\"Female\",\"age\":\"Adult\",\"weight_kg\":\"24.3\",\"microchip\":\"\",\"animal_id\":\"\",\"intake_type\":\"Wildlife admission: vehicle strike\"},\n\"visit\":{\"type\":\"Clinical consult\",\"clinician\":\"\"},\n\"subjective\":\"Adult female wombat struck by a vehicle on the Bass Highway near Kilcunda last night. Brought in by a carer this morning.\",\n\"objective\":{\"vitals\":{\"temp_c\":\"36.1\",\"hr_bpm\":\"82\",\"rr_bpm\":\"22\",\"bcs\":\"\",\"mm_crt\":\"MM pink, CRT <2 s\",\"hydration\":\"\"},\n\"findings\":[\"BAR; hissing on handling.\",\"Body weight 24.3 kg.\",\"Skin: sarcoptic mange, moderate, affecting approximately 30% of the body. Crusting over both flanks and both pinnae. Early fissuring around the left eye.\",\"Left shoulder: superficial abrasion, 3 x 2 cm, contaminated.\",\"Musculoskeletal: no fractures palpable; ambulating normally.\",\"Neurological: no deficits detected.\",\"Pouch empty; not lactating.\"],\n\"photo_findings\":[]},\n\"assessment\":{\"problems\":[\"1. Sarcoptic mange, moderate (approximately 30% body surface): crusting of both flanks and both pinnae, early periocular fissuring of the left eye.\",\"2. Superficial contaminated abrasion, left shoulder (3 x 2 cm).\"],\n\"differentials\":[],\n\"prognosis\":\"Good\"},\n\"plan\":{\"procedures\":[\"Left shoulder abrasion cleaned with dilute chlorhexidine (Hibiclens).\"],\n\"diagnostics\":[],\n\"treatments\":[{\"drug\":\"Cydectin (moxidectin) pour-on\",\"dose\":\"0.8 mL/kg (19.4 mL as stated), per permit\",\"route\":\"Topical (pour-on)\",\"frequency\":\"Once\",\"duration\":\"\",\"when\":\"given\"},\n{\"drug\":\"Meloxicam (Metacam)\",\"dose\":\"0.2 mg/kg\",\"route\":\"SC\",\"frequency\":\"Once\",\"duration\":\"\",\"when\":\"given\"},\n{\"drug\":\"Cydectin (moxidectin) pour-on\",\"dose\":\"0.8 mL/kg, per permit\",\"route\":\"Topical (pour-on)\",\"frequency\":\"Weekly\",\"duration\":\"15 weeks\",\"when\":\"continue\"}],\n\"hospital_plan\":[],\n\"home_care\":[\"House in a quiet pen with a hide box.\",\"Keep handling to a minimum.\",\"Carer to repeat the Cydectin pour-on weekly for 15 weeks.\",\"Weigh weekly.\"],\n\"follow_up\":[\"Recheck in 1 week.\"]},\n\"welfare_notes\":\"\",\n\"check\":[\"'Side deck tin' read as Cydectin (moxidectin): correct?\",\"Carer authorised under permit to apply Cydectin?\"]}]}",
  "70vpxslbzf": "```json\n{\"animal\":\"Common ringtail possum joey (female, about 120 g, furred, eyes open)\",\"species\":\"Common ringtail possum (Pseudocheirus peregrinus)\",\"kind\":\"wildlife\",\"summary\":\"This young female ringtail was caught by a cat in Wonthaggi yesterday, and the vet checked her this morning, found no puncture wounds and started her on a course of antibiotics. The goal is to finish her antibiotics, wean her onto native browse alongside other ringtails, and release her near where she was found.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Antibiotic dispensed by the vet (to prevent infection after the cat attack, since cat saliva carries harmful bacteria)\",\"how\":\"As dispensed by the clinic\",\"how_often\":\"Once a day\",\"how_long\":\"5 days in total, finishing the whole course\",\"tip\":\"Give it at the same time each day, just before a milk feed.\"}],\n\"plan\":[{\"when\":\"Days 1 to 5\",\"tasks\":[\"Give the antibiotic course to fight any hidden infection from the cat attack.\"]},{\"when\":\"Day 6\",\"tasks\":[\"Antibiotic finished.\"]},{\"when\":\"From about 160 days old (rising leaf intake, around 150 to 200 g)\",\"tasks\":[\"Slowly reduce her milk while she eats more browse, aiming to stop milk at about 180 days old.\"]},{\"when\":\"Once fully weaned (about 310 g)\",\"tasks\":[\"Move her to a larger pre-release enclosure with her ringtail group.\"]}],\n\"housing\":[\"Keep her in her pouch inside a small enclosure, with a heat pad set to about 30°C under one end only so she can move off it if too warm.\",\"Keep the enclosure in a quiet, dim room away from pets, children and household noise.\",\"Add sturdy branches for climbing and hang fresh browse within easy reach.\",\"Change pouch liners daily, sterilise bottles and teats before every feed, and wash your hands before and after handling her.\"],\n\"feeding\":[\"Feed Wombaroo Possum Milk Replacer >0.8, made with 25 g of powder (3½ scoops) and 80 mL of warm pre-boiled water, warmed to about 30°C; never give cow's milk, as it gives possum joeys diarrhoea.\",\"Feed every 4 hours, about 4 feeds a day, using the feed calculator amount for today's weight, then toilet her after each feed by gently stroking her bottom with a damp soft cloth.\",\"Offer fresh native browse daily, ideally 3 to 5 eucalypt species, and expect her to eat some of her own droppings, which ringtails need for healthy digestion.\",\"Hold off on all fruit, vegetables and flowers until she is over 250 g, and never give cabbage-family plants, lantana, oleander or hydrangea, as the wrong diet is a leading cause of bloat in ringtails.\",\"Provide a shallow dish of fresh water changed daily, and in hot weather offer extra water between feeds rather than diluting her milk.\"],\n\"activity\":[\"Handle her gently and only for feeds, toileting, weighing and medication, wearing gloves and long sleeves.\",\"Ringtails are social, so she should be raised with other young ringtails through an experienced carer and released with them.\",\"Avoid taming or cuddling her and keep pets well away, so she keeps her natural fear of people and predators.\"],\n\"care\":[\"Keep her record up to date with her case number, the exact Wonthaggi location where she was found (GPS or Melways), weights, treatments and outcome, and keep it for 3 years.\"],\n\"daily_checks\":[\"Weight before feed\",\"Antibiotic given\",\"Wees and poos\",\"Browse eaten\",\"Skin and fur check\"],\"log_days\":5,\n\"feed_calc\":{\"applies\":true,\"what\":\"Wombaroo Possum Milk Replacer >0.8\",\"weight_g\":120,\"stage\":\"Furred, eyes open, about 130 to 135 days old (Age Factor over 0.8)\",\"percent_body_weight_per_day\":14,\"feeds_per_day\":4,\"basis\":\"Wombaroo Milk Booklet common ringtail chart, about 17 mL a day at 120 g, converted to percent of body weight\",\"sure\":false},\n\"release\":{\"ready_when\":[\"Fully weaned and eating native browse only\",\"Healthy, active and climbing well, with no remaining injuries\",\"Wary of people and building or using a nest\",\"At release weight and age, around 600 g\"],\"target_weight\":\"About 600 g for a common ringtail possum\",\"how\":[\"Release within 24 hours of being ready, together with her ringtail group.\",\"Use a soft release, with a temporary nest box and supplementary browse at the site.\",\"Release at dusk, never during the day.\",\"Avoid extreme heat, cold, wind or heavy rain.\"],\"where\":\"Release her where she was found in Wonthaggi, or if that spot is unsuitable, at the closest suitable place within her home range.\"},\n\"escalate\":{\"vet\":[\"Redness, swelling, a lump, a smell or discharge anywhere on her skin, which can mean a hidden cat-bite infection.\",\"Diarrhoea, or refusing milk for more than one feed.\",\"Weight loss on two days in a row.\",\"Dull, sleepy or not interested in browse.\"],\"urgent\":[\"A swollen, tight or drum-like belly, which can mean bloat.\",\"Breathing with effort, open-mouth breathing or clicking sounds.\",\"Cold, floppy or collapsed: keep her warm and give nothing by mouth on the way.\",\"Bleeding or a newly found wound.\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"ringtail\",\n\"next_visit\":\"\",\"sources\":[\"vic-cop-welfare-wildlife-rehabilitation\",\"vic-release-requirements\",\"vic-rehabilitator-authorisation-conditions\",\"vic-shelter-foster-carer-authorisation\",\"vic-rehab-guidelines-part-a\",\"wombaroo-milk-replacers-feeding-guide\",\"wires-possums\"]}\n```",
  "1x4fpyjucrf": "{\"title\":\"Wombat with mange recovering after being hit by a car near Kilcunda\",\"subtitle\":\"Media statement\",\"sections\":[{\"heading\":\"Statement\",\"text\":\"An adult female wombat is in care at Bunurong Wildlife Care in Inverloch after being hit by a car on the Bass Highway near Kilcunda last night. A wildlife carer brought her in this morning.\\n\\nOur vet found no broken bones and no signs of injury to her nerves or spine. She is walking normally, and she has a graze on her left shoulder, which has been cleaned. She weighs 24.3 kg, is alert and is letting us know she would rather be left alone. She was not carrying a joey.\\n\\nShe also has moderate mange, a skin disease that had caused crusting across about 30 per cent of her body, including both sides and both ears. She has started treatment and has been given pain relief. She is now resting in a quiet pen with a hiding box and is being handled as little as possible. She will need mange treatment every week for 15 weeks, regular weigh-ins and a vet check in a week. Her outlook is good.\\n\\nMany wombats are hit on our roads, particularly around dawn and dusk when they are most active. Slowing down and watching the roadside on these stretches can save their lives. Calling for help quickly also gives an injured animal the best chance.\"},{\"heading\":\"Quote\",\"text\":\"\\\"She was very lucky. There are no broken bones and she's walking normally, so her outlook is good. With quiet rest and weekly mange treatment over the next 15 weeks, she has every chance of a full recovery,\\\" said [Name], [role].\"},{\"heading\":\"What the public can do\",\"items\":[\"Slow down at dawn, dusk and night, when wombats are most active near roads.\",\"If you see an injured, sick or orphaned native animal, call Wildlife Victoria's free 24/7 emergency line on (03) 8400 7300. Have the location ready as a dropped pin or GPS coordinates.\",\"Don't approach an injured adult wombat. Keep your distance and wait for a trained rescuer.\",\"If you see a wombat with mange, note exactly where it was and which parts of its body are affected when you report it.\"]},{\"heading\":\"About the organisation\",\"text\":\"Bunurong Wildlife Care is a registered wildlife shelter and charity in Inverloch, Victoria.\"},{\"heading\":\"Not for publication\",\"items\":[\"Drug names, doses and clinical findings are kept out of the release.\",\"The cracked skin around her left eye has been left out as a graphic detail.\",\"The carer has not been named, as no consent has been given.\"]}],\"due\":[{\"what\":\"Vet recheck\",\"when\":\"In 1 week\"},{\"what\":\"Repeat mange pour-on (carer)\",\"when\":\"Weekly for 15 weeks\"},{\"what\":\"Weigh\",\"when\":\"Weekly\"}],\"check\":[\"Spokesperson name and role for the quote?\",\"Was 'side deck tin' Cydectin (moxidectin)?\",\"Date to put on the statement?\",\"Media contact name and details?\",\"Okay to name the Bass Highway near Kilcunda?\"]}",
  "2cn08jk16zb": "```json\n{\"animal\":\"Adult female wombat\",\"species\":\"Common (bare-nosed) wombat (Vombatus ursinus)\",\"kind\":\"wildlife\",\"summary\":\"Thank you for caring for this wombat. She is an adult female hit by a car on the Bass Highway near Kilcunda, with a small grazed left shoulder and moderate mange; she had her first mange treatment, a pain-relief injection of meloxicam (Metacam) and her graze cleaned at the clinic. Her outlook is good, and the goal is to clear her mange and get her home to her own patch.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Cydectin (moxidectin) pour-on (for mange)\",\"how\":\"Pour 19.4 mL slowly along the middle of her back from shoulders to rump. A scoop on a long pole lets you do this without handling her.\",\"how_often\":\"Once a week, on the same day each week\",\"how_long\":\"15 weeks in total. The first dose was given today, so the next is due in 7 days.\",\"tip\":\"It is a registered poison and toxic to water insects, so wear gloves and eye protection, and keep spills out of drains and waterways.\"}],\n\"plan\":[{\"when\":\"Day 7 (1 week from today)\",\"tasks\":[\"Recheck with your vet, who will look at the graze and her mange and confirm whether she stays in care or is released and treated where she lives.\",\"Second weekly Cydectin dose is due.\"]},{\"when\":\"Week 15\",\"tasks\":[\"Final Cydectin dose, then the course is finished.\"]}],\n\"housing\":[\"Keep her in a quiet, dig-proof pen with a hide box, well away from pets, people and other wildlife.\",\"Keep the pen cool and shaded and follow the temperatures shown in the app, because wombats cannot sweat and overheat easily.\",\"Keep her in strict quarantine with her own equipment, and service her last. Wear gloves and long sleeves and wash your hands afterwards, because mange (and sometimes salmonella or ringworm) can pass to people.\",\"Remove droppings every day and keep straw free of cat droppings. Hot-wash and hot-dry her bedding, and after she leaves, clean the pen and leave it empty for at least three weeks.\"],\n\"feeding\":[\"Give fresh grass (ideally native grasses with roots) as her main food, with grass hay always available.\",\"Grass-based pellets can be a small extra of no more than a tenth of her daily food. Never give cattle or chicken pellets, because their coccidiostats can kill wombats.\",\"Never give bread, cereal biscuits or muesli mixes, because they cause bloat and gum infections.\",\"Keep fresh water in a heavy, shallow bowl and change it every day.\",\"Put fresh food out in the evening, when she is active, and note how much she eats overnight.\"],\n\"activity\":[\"Handle her as little as possible and never corner or try to lift her: an adult wombat can bite, scratch and crush hands with her hard rump.\",\"Do not fuss over or tame her, because she needs to stay wary of people to survive back in the wild.\",\"Give her a patch of soil to dig in and scatter cut grass so she can forage.\"],\n\"care\":[\"Weigh her once a week, on her Cydectin day, by coaxing her onto a platform scale or weighing her in a crate, never by wrestling her.\",\"Record every treatment (date, product, amount and how she looks), plus the exact place she was found near Kilcunda, with GPS coordinates if possible, so she can go home.\",\"Tell Mange Management (mangemanagement.org.au) about her so her mange treatment can be coordinated.\"],\n\"daily_checks\":[\"Eating grass and hay\",\"Droppings normal\",\"Graze clean, no flies\",\"Left eye open, clear\",\"Walking steadily\"],\"log_days\":14,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24300,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult wombat eating grass and hay, not a measured milk feed\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Graze fully healed and she needs no more medical care\",\"Mange scabs falling away and fur regrowing, with her eyes clear\",\"Eating well and holding her weight\",\"Still wary of people\"],\"target_weight\":\"About her admission weight of 24.3 kg or more\",\"how\":[\"Release her within 24 hours of being ready, but not in extreme heat, storms or heavy rain.\",\"Transport her in an air-conditioned car, in a sturdy ventilated crate rather than a soft bag.\",\"Release about an hour after dusk, ideally at an unoccupied burrow within about 150 m of where she was found.\",\"Open the crate and let her leave in her own time.\"],\"where\":\"Release her where she was found near Kilcunda, set back from the Bass Highway in suitable bush within her home range, on the same side of the road she was found if known, never somewhere she would not normally cross into.\"},\n\"escalate\":{\"vet\":[\"The graze becomes red, swollen, smelly or has flies or maggots on it.\",\"She stops eating for a day, or has diarrhoea or constipation lasting more than 24 hours.\",\"Crusting around her left eye gets worse, or the eye becomes cloudy, weepy or stays closed.\",\"She is losing weight from one week to the next.\"],\"urgent\":[\"She is wobbly, drowsy, drooling, slow to respond or lying down after a Cydectin dose.\",\"Heat stress signs: red feet, drooling onto her chest and front legs, or lying on her back.\",\"Collapse, or difficulty breathing.\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":24300,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Recheck in 1 week\",\"sources\":[\"vic-rehab-guidelines-wombats\",\"vic-mange-management\",\"vic-release-requirements\",\"vic-rehabilitator-authorisation-conditions\",\"vic-cop-welfare-wildlife-rehabilitation\",\"vic-shelter-foster-carer-authorisation\",\"vic-rehab-guidelines-part-a\",\"au-sarcoptic-mange-treatment-sheet\"]}\n```",
  "2c03u4bhd69": "{\"animals\":[{\"patient\":{\"name\":\"\",\"species\":\"Wombat\",\"breed\":\"\",\"sex\":\"Female\",\"age\":\"Adult\",\"weight_kg\":\"24.3\",\"microchip\":\"\",\"animal_id\":\"\",\"intake_type\":\"\"},\n\"visit\":{\"type\":\"Clinical consult\",\"clinician\":\"\"},\n\"subjective\":\"Adult female wombat, previously seen (dictated as the same wombat). Dictation focused on the carer plan. Planned release site is the Kilcunda pull-over.\",\n\"objective\":{\"vitals\":{\"temp_c\":\"\",\"hr_bpm\":\"\",\"rr_bpm\":\"\",\"bcs\":\"\",\"mm_crt\":\"\",\"hydration\":\"\"},\"findings\":[\"Body weight 24.3 kg.\",\"Skin: changes consistent with mange, moderate severity.\",\"Superficial graze over the left shoulder.\"],\"photo_findings\":[]},\n\"assessment\":{\"problems\":[\"1. Mange, moderate.\",\"2. Superficial graze, left shoulder.\"],\"differentials\":[],\"prognosis\":\"\"},\n\"plan\":{\"procedures\":[],\"diagnostics\":[],\"treatments\":[{\"drug\":\"Cydectin (moxidectin) pour-on\",\"dose\":\"\",\"route\":\"Topical\",\"frequency\":\"Once\",\"duration\":\"\",\"when\":\"given\"},{\"drug\":\"Cydectin (moxidectin) pour-on\",\"dose\":\"19.4 mL\",\"route\":\"Topical, along the spine\",\"frequency\":\"Once weekly, same day each week\",\"duration\":\"15 weeks\",\"when\":\"continue\"},{\"drug\":\"Meloxicam (Metacam)\",\"dose\":\"\",\"route\":\"\",\"frequency\":\"Once\",\"duration\":\"\",\"when\":\"given\"}],\"hospital_plan\":[],\"home_care\":[\"Apply Cydectin pour-on along the spine once weekly on the same day each week, wearing gloves.\",\"No meloxicam to be given at home.\",\"Clean the left shoulder graze once daily with saline.\",\"House in a quiet pen with a hide box and straw bedding. Keep handling to a minimum and keep dogs away.\",\"Diet: grass hay, fresh native grasses and clean water. A few carrots are acceptable.\",\"Weigh weekly on the same scales.\"],\"follow_up\":[\"Recheck in 1 week.\",\"Contact the vet if she stops eating, the graze becomes hot or malodorous, or the periocular skin bleeds.\",\"Release at the Kilcunda pull-over once the coat is regrowing and the skin has healed.\"]},\n\"welfare_notes\":\"\",\n\"check\":[\"Meloxicam dose and route given today?\",\"Cydectin dose given today: 19.4 mL?\",\"Carer APVMA permit and Wildlife Act authorisation for Cydectin?\"]}]}",
  "1gcg9go6u8t": "```json\n{\"animal\":\"Adult female wombat, 24.3 kg\",\"species\":\"Common (bare-nosed) wombat\",\"kind\":\"wildlife\",\"summary\":\"Thank you for caring for this wombat. She is an adult female with moderate mange and a shallow graze on her left shoulder, and today she had her first Cydectin (moxidectin) treatment and a dose of meloxicam (Metacam) for pain. The goal is to clear the mange, heal her skin and get her home to Kilcunda as soon as she is ready.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Cydectin pour-on (moxidectin, for mange mites)\",\"how\":\"Pour 19.4 mL in a line along her spine, wearing gloves and eye protection\",\"how_often\":\"Once a week, on the same day each week\",\"how_long\":\"15 weeks (today's clinic dose was the first, so check with your vet whether it counts as week one)\",\"tip\":\"Apply while she rests in her hide box so you barely need to touch her, and keep the product and any rinse water away from drains and waterways, as it harms water insects.\"}],\n\"plan\":[{\"when\":\"In 1 week\",\"tasks\":[\"Recheck with the vet.\",\"Give the second weekly Cydectin dose.\"]},{\"when\":\"Week 15\",\"tasks\":[\"Give the final Cydectin dose.\"]}],\n\"housing\":[\"Keep her in a quiet pen with a hide box and straw bedding, well away from dogs, other pets and other wildlife, and care for her last each day.\",\"Keep the pen cool and shaded, because wombats overheat easily and handle cold far better than heat.\",\"Remove droppings every day and keep the straw free of cat droppings to prevent coccidia and toxoplasma.\",\"Hot-wash and hot-dry bedding, because mange mites survive in bedding for up to 3 weeks, and leave the pen clean and empty for at least 3 weeks after she leaves.\"],\n\"feeding\":[\"Give grass hay and fresh native grasses as her main food.\",\"Offer clean water in a heavy dish and change it daily.\",\"A few carrots are fine, as your vet advised. Carrots are used as rabbit bait, so I'm not certain they suit a wombat going back to the wild; check with your vet.\",\"Never give cattle or chicken pellets, which can contain drugs that are fatal to wombats, or bread, biscuits or muesli, which cause bloat and gum infections.\"],\n\"activity\":[\"Handle her as little as possible, keep visits short and calm, and never try to tame her, because adult wombats stress easily in captivity.\",\"Wear gloves and long sleeves around her and wash your hands afterwards, because mange can pass to people as an itchy rash.\",\"Keep your hands clear of her rump and the hide box walls, because she can bite and can crush hands with her rump plate.\"],\n\"care\":[\"Clean the shoulder graze once a day with saline, and keep flies off it in warm weather.\",\"Weigh her once a week on the same scales.\",\"Record each Cydectin dose (date, amount, how she responded), her weekly weight and the graze's progress in her record.\"],\n\"daily_checks\":[\"Eating hay and grass\",\"Graze clean and dry\",\"Skin around eyes\",\"Droppings removed\",\"Fresh water\"],\n\"log_days\":7,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24300,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult on a grass and hay diet; no measured milk feeds.\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Coat is growing back over the mange patches\",\"Skin and shoulder graze have healed\",\"Eating well and holding her weight\",\"Wary of people and keeping to her hide box\"],\"target_weight\":\"About 24 kg, holding or gaining on her admission weight\",\"how\":[\"Release within 24 hours of her being ready, and not in extreme heat or storms.\",\"Release about an hour after dusk, ideally at an empty burrow within about 150 m of where she was found.\",\"Open the carrier and let her leave in her own time.\"],\"where\":\"Release her back at the Kilcunda pull-over where she was found, or at the closest suitable spot within her home range.\"},\n\"escalate\":{\"vet\":[\"She stops eating.\",\"The graze becomes hot, swollen or smelly.\",\"The skin around her eye bleeds.\",\"Scabs spread or new raw patches appear.\"],\"urgent\":[\"She is wobbly, drowsy, drooling or lying down and unresponsive after a Cydectin dose.\",\"Signs of heat stress: red feet, drooling on her chest or forelegs, or lying on her back.\",\"Fly eggs or maggots on her skin or graze.\",\"Collapse or trouble breathing.\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Recheck with the vet in 1 week\",\"sources\":[\"vic-rehab-guidelines-wombats\",\"vic-cop-welfare-wildlife-rehabilitation\",\"vic-release-requirements\",\"vic-rehabilitator-authorisation-conditions\",\"vic-shelter-foster-carer-authorisation\",\"vic-mange-management\",\"vic-rehab-guidelines-part-a\",\"au-sarcoptic-mange-treatment-sheet\"]}\n```",
  "jj7pp7uf1l": "{\"polished\":\"Willow, juvenile female wombat, recheck.\\nWeight: 6.0 kg, down from 6.2 kg last week. BCS 4/9.\\nHistory: Eating fewer pellets, still grazing. Loose faeces for 2 days.\\nExam: BAR. T 35.8 °C. Mange improving, with fur regrowth on both flanks. Pinnae still crusty.\\nFaecal float: negative.\\nPlan:\\nContinue moxidectin pour-on weekly, 2 more doses.\\nAdd probiotic 1 sachet SID for 5 days.\\nReweigh in 3 days.\\nOK for outdoor enclosure once faeces are normal.\",\"animals\":[{\"patient\":{\"name\":\"Willow\",\"species\":\"Bare-nosed wombat (assumed)\",\"breed\":\"\",\"sex\":\"Female\",\"age\":\"Juvenile\",\"weight_kg\":\"6.0\",\"microchip\":\"\",\"animal_id\":\"\",\"intake_type\":\"\"},\"visit\":{\"type\":\"Clinical consult\",\"clinician\":\"\"},\"subjective\":\"Juvenile female wombat in care, presented for recheck. Weight has decreased to 6.0 kg from 6.2 kg last week. She is eating fewer pellets but is still grazing. Loose faeces have been present for 2 days.\",\"objective\":{\"vitals\":{\"temp_c\":\"35.8\",\"hr_bpm\":\"\",\"rr_bpm\":\"\",\"bcs\":\"4/9\",\"mm_crt\":\"\",\"hydration\":\"\"},\"findings\":[\"BAR.\",\"Weight 6.0 kg, down from 6.2 kg last week.\",\"Pinnae: crusting persists.\",\"Flanks: fur regrowth on both flanks.\",\"Faecal float: negative.\"],\"photo_findings\":[]},\"assessment\":{\"problems\":[\"1. Sarcoptic mange: improving, with residual crusting of the pinnae.\",\"2. Loose faeces for 2 days; faecal float negative.\"],\"differentials\":[],\"prognosis\":\"\"},\"plan\":{\"procedures\":[],\"diagnostics\":[],\"treatments\":[{\"drug\":\"Moxidectin (Cydectin) pour-on\",\"dose\":\"\",\"route\":\"Topical\",\"frequency\":\"Weekly\",\"duration\":\"2 more doses\",\"when\":\"continue\"},{\"drug\":\"Probiotic\",\"dose\":\"1 sachet\",\"route\":\"PO (assumed)\",\"frequency\":\"SID\",\"duration\":\"5 days\",\"when\":\"continue\"}],\"hospital_plan\":[],\"home_care\":[],\"follow_up\":[\"Reweigh in 3 days.\",\"Move to outdoor enclosure once faeces are normal.\"]},\"welfare_notes\":\"\",\"check\":[\"Moxidectin pour-on dose per current protocol?\",\"Probiotic given PO?\",\"Species bare-nosed wombat?\"]}]}",
  "nybk1u0iyf": "```json\n{\"animal\":\"Adult female wombat\",\"species\":\"Common (bare-nosed) wombat\",\"kind\":\"wildlife\",\"summary\":\"This adult female wombat was hit by a car on the Bass Highway near Kilcunda and has moderate mange with crusting on her sides, ears and around her left eye, plus a grazed left shoulder; the clinic cleaned the graze and gave her a pain-relief injection and her first mange treatment. The goal is to clear her mange and heal her skin so she can go back to where she was found.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Cydectin pour-on, moxidectin (for mange)\",\"how\":\"Pour 0.8 mL per kg of her body weight onto her skin along her back (19.4 mL at her current 24.3 kg), as dispensed by the clinic\",\"how_often\":\"Once a week\",\"how_long\":\"15 weeks\",\"tip\":\"Recalculate the dose from her weekly weight, and move slowly and calmly while you pour so you don't have to chase her.\"}],\n\"plan\":[{\"when\":\"Day 7 (one week after the clinic visit)\",\"tasks\":[\"Her first home dose of Cydectin is due.\"]},{\"when\":\"Week 15\",\"tasks\":[\"Give her last Cydectin dose, then check her against the release signs.\"]}],\n\"housing\":[\"Keep her alone in a quiet pen with a hide box, away from other wildlife, pets and household noise.\",\"Feed and clean her last, after any other animals in your care, because mange spreads.\",\"People can catch mange, so wear gloves and protective clothing when you clean or touch her, and wash your hands well afterwards.\",\"Keep her at the enclosure temperature the app shows, and after she leaves, clean her pen and leave it empty for at least three weeks.\"],\n\"feeding\":[\"Feed mainly fresh grasses, offered with their roots and dirt, plus hay.\",\"Give fresh water every day in a heavy dish she can't tip over.\",\"Don't feed bread, cereal biscuits or muesli mixes, because they cause gum infections and bloat.\",\"Don't feed chaff, carrots, fresh clover, cabbage or phalaris grass, because clover and cabbage cause bloat.\",\"Never give cattle or chicken pellets, because they can contain medicines that are deadly to wombats.\"],\n\"activity\":[\"Handle her as little as possible, and quickly and gently when you must, because she is a wild adult and will hiss and defend herself.\",\"Don't tame her or let visitors see her, so she keeps her fear of people.\",\"Give her deep soil or hay to dig in, and fresh grass sods to forage.\"],\n\"care\":[\"Weigh her once a week, which you need for working out her Cydectin dose.\",\"Record every dose with the date, amount and how she's going, along with her rescue details and exact find location, and keep these records for 3 years.\",\"In warm weather, protect her scabs and the shoulder graze from flies.\"],\n\"daily_checks\":[\"Eating grass and hay\",\"Drinking water\",\"Shoulder graze clean\",\"Left eye looks okay\",\"Normal droppings\"],\"log_days\":14,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24300,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult wombat eating grass and hay, not fed a measured milk amount\",\"sure\":true},\n\"release\":{\"ready_when\":[\"All scabs have gone and her skin, ears and eye area have healed\",\"She has finished her treatment and needs no more medical care\",\"She is eating well, has adequate fur and moves normally\",\"She is wary of people and behaves like a wild wombat\"],\"target_weight\":\"\",\"how\":[\"Release her within 24 hours of being ready, but not in extreme weather.\",\"Release about an hour after dusk, ideally at an empty burrow within about 150 m of where she was found.\",\"Open the box and let her leave in her own time.\"],\"where\":\"Release her where she was found near Kilcunda, or if that spot is unsuitable, at the closest suitable place within her home range without crossing a barrier she wouldn't normally cross.\"},\n\"escalate\":{\"vet\":[\"The shoulder graze becomes red, swollen or smelly, or has pus.\",\"Her left eye becomes weepy, cloudy or more cracked, or she keeps it shut.\",\"She stops eating for a day, or loses weight between weigh-ins.\",\"Her scabs spread or get worse despite treatment.\"],\"urgent\":[\"You see fly eggs or maggots on her, or notice a rotting smell.\",\"She collapses, can't stand or becomes wobbly.\",\"She has trouble breathing.\",\"She develops sudden lameness, swelling or bleeding, which could mean a hidden injury from the car strike.\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Recheck with the vet in 1 week.\",\"sources\":[\"vic-rehab-guidelines-wombats\",\"vic-release-requirements\",\"vic-cop-welfare-wildlife-rehabilitation\",\"vic-rehabilitator-authorisation-conditions\",\"vic-shelter-foster-carer-authorisation\",\"vic-mange-management\",\"vic-rehab-guidelines-part-a\",\"au-sarcoptic-mange-treatment-sheet\"]}\n```",
  "18z6c5inwwn": "{\"title\":\"Wombat named Hope returns home after nine weeks in care\",\"subtitle\":\"Media statement, Inverloch, Victoria\",\"sections\":[{\"heading\":\"Statement\",\"text\":\"A wombat hit by a vehicle on the Bass Highway near Kilcunda in August went back to her burrow this morning after nine weeks in care with Bunurong Wildlife Care in Inverloch.\\n\\nThe wombat, named Hope by her carers, came in with severe mange over most of her body and a graze on her shoulder. During her time in care she had six weekly mange treatments and put on two kilograms. She went home with a full coat of fur.\\n\\nHope is one of 70 wombats Bunurong Wildlife Care has taken in so far this year. The shelter is asking drivers to slow down on the Bass Highway at dawn and dusk. It is also asking anyone who sees a wombat with mange to report it rather than trying to treat it themselves.\",\"items\":[]},{\"heading\":\"Quote\",\"text\":\"\\\"Watching her walk back into her own burrow, with a full coat of fur, is exactly why we do this,\\\" said Dr Sam Lee, senior veterinarian at Bunurong Wildlife Care.\",\"items\":[]},{\"heading\":\"What the public can do\",\"text\":\"\",\"items\":[\"Slow down on the Bass Highway at dawn and dusk.\",\"If you see a wombat with mange, report it rather than trying to treat it yourself. Note the exact location and which parts of its body are affected.\",\"Do not approach an injured adult wombat. Call Wildlife Victoria's free 24/7 emergency line on (03) 8400 7300 and wait for help.\",\"Have the location ready as a dropped pin or GPS coordinates. Do not use social media to report wildlife emergencies.\"]},{\"heading\":\"About the organisation\",\"text\":\"Bunurong Wildlife Care is a registered wildlife shelter and charity in Inverloch, Victoria.\",\"items\":[]},{\"heading\":\"Not for publication\",\"text\":\"Do not publish the exact location of Hope's burrow. Refer only to the general area, near Kilcunda.\",\"items\":[]}],\"due\":[],\"check\":[\"What date was Hope released?\",\"Who is the media contact, and what are their details?\",\"Was Hope's mange found after the vehicle strike?\",\"Is it OK to name Kilcunda publicly?\",\"Is it OK to use photos of Hope?\"]}",
  "25okmyd8tyn": "{\"polished\":\"Willow, juvenile female wombat, recheck.\\nWeight: 6.0 kg, down from 6.2 kg last week. BCS 4/9.\\nHistory: Eating fewer pellets, still grazing. Loose faeces for 2 days.\\nExam: BAR. T 35.8 °C. Mange improving, with fur regrowth on both flanks. Pinnae still crusty.\\nFaecal float: negative.\\nPlan:\\nContinue moxidectin pour-on weekly, 2 more doses.\\nAdd probiotic 1 sachet SID for 5 days.\\nReweigh in 3 days.\\nOK for outdoor enclosure once faeces are normal.\",\"animals\":[{\"patient\":{\"name\":\"Willow\",\"species\":\"Bare-nosed wombat (assumed)\",\"breed\":\"\",\"sex\":\"Female\",\"age\":\"Juvenile\",\"weight_kg\":\"6.0\",\"microchip\":\"\",\"animal_id\":\"\",\"intake_type\":\"\"},\"visit\":{\"type\":\"Clinical consult\",\"clinician\":\"\"},\"subjective\":\"Juvenile female wombat in care, presented for recheck. Weight has decreased to 6.0 kg from 6.2 kg last week. She is eating fewer pellets but is still grazing. Loose faeces have been present for 2 days.\",\"objective\":{\"vitals\":{\"temp_c\":\"35.8\",\"hr_bpm\":\"\",\"rr_bpm\":\"\",\"bcs\":\"4/9\",\"mm_crt\":\"\",\"hydration\":\"\"},\"findings\":[\"BAR.\",\"Weight 6.0 kg, down from 6.2 kg last week.\",\"Pinnae: crusting persists.\",\"Flanks: fur regrowth on both flanks.\",\"Faecal float: negative.\"],\"photo_findings\":[]},\"assessment\":{\"problems\":[\"1. Sarcoptic mange: improving, with residual crusting of the pinnae.\",\"2. Loose faeces for 2 days; faecal float negative.\"],\"differentials\":[],\"prognosis\":\"\"},\"plan\":{\"procedures\":[],\"diagnostics\":[],\"treatments\":[{\"drug\":\"Moxidectin (Cydectin) pour-on\",\"dose\":\"\",\"route\":\"Topical\",\"frequency\":\"Weekly\",\"duration\":\"2 more doses\",\"when\":\"continue\"},{\"drug\":\"Probiotic\",\"dose\":\"1 sachet\",\"route\":\"PO (assumed)\",\"frequency\":\"SID\",\"duration\":\"5 days\",\"when\":\"continue\"}],\"hospital_plan\":[],\"home_care\":[],\"follow_up\":[\"Reweigh in 3 days.\",\"Move to outdoor enclosure once faeces are normal.\"]},\"welfare_notes\":\"\",\"check\":[\"Moxidectin pour-on dose per current protocol?\",\"Probiotic given PO?\",\"Species bare-nosed wombat?\"]}]}",
  "eff86bnzsj": "{\"title\":\"Oliver (eastern grey kangaroo joey) care log\",\"subtitle\":\"Thursday\",\"sections\":[{\"heading\":\"Summary\",\"text\":\"Oliver is feeding well, gaining weight and spending more time out of the pouch.\"},{\"heading\":\"Weight\",\"text\":\"2.31 kg this morning, up 40 g from Monday.\"},{\"heading\":\"Feeding\",\"items\":[\"Four bottle feeds of Wombaroo 0.7, 120 mL each\",\"Took all feeds, the last one a bit slowly\",\"Started picking at kangaroo grass\"]},{\"heading\":\"Toileting\",\"text\":\"Toileted after every feed with stimulation. Normal pellets.\"},{\"heading\":\"Behaviour and condition\",\"text\":\"Spending more time out of the pouch and hopping around the room.\"},{\"heading\":\"Wounds and treatment\",\"text\":\"Small scrape on his tail from the pen door, cleaned with saline.\"},{\"heading\":\"To watch\",\"items\":[\"Small tail scrape. Consider a vet check if it looks worse or doesn't heal.\"]}],\"due\":[{\"what\":\"Weigh\",\"when\":\"Monday\"}],\"check\":[\"Is Wombaroo 0.7 the Kangaroo Milk Replacer >0.7?\",\"Anything behind the slower last feed?\",\"Has the pen door been made safe?\"]}",
  "5fmk85w1f0": "{\"title\":\"Rescue and intake record: adult female bare-nosed wombat\",\"subtitle\":\"Wildlife Victoria case 26-04417\",\"sections\":[{\"heading\":\"Register entry\",\"text\":\"\",\"items\":[\"Case number: 26-04417 (Wildlife Victoria)\",\"Common name: Bare-nosed wombat\",\"Species code: Not recorded\",\"Date in: Not recorded\",\"Sex (M, F or U): F\",\"Age class: Adult\",\"Main injury: Graze to left shoulder; severe mange\",\"Cause: Hit by a car\",\"Where found: The gravel pull-over on the south side of the highway, just east of the Kilcunda bridge (Bass Highway near Kilcunda)\",\"Status: In care\"]},{\"heading\":\"Rescue details\",\"text\":\"\",\"items\":[\"Hit by a car last night on the Bass Highway near Kilcunda.\",\"A motorist called it in at about 9 pm.\",\"Picked up by the carer at 9.40 pm.\",\"Wildlife Victoria case 26-04417.\"]},{\"heading\":\"Where it was found\",\"text\":\"The gravel pull-over on the south side of the highway, just east of the Kilcunda bridge (Bass Highway near Kilcunda).\",\"items\":[]},{\"heading\":\"Animal\",\"text\":\"\",\"items\":[\"Species: Bare-nosed wombat\",\"Sex: Female\",\"Age: Adult\",\"Weight: About 24 kg\"]},{\"heading\":\"Condition on arrival\",\"text\":\"\",\"items\":[\"Pouch empty.\",\"Severe mange over both flanks and the back.\",\"Crusting on both ears.\",\"Graze on the left shoulder.\",\"Walking okay; no obvious fractures.\",\"Alert and hissing.\"]},{\"heading\":\"First aid and care given\",\"text\":\"\",\"items\":[\"Placed in the quiet pen with a hide box and water.\"]},{\"heading\":\"Vet\",\"text\":\"\",\"items\":[\"Booked with the Wildlife Victoria travelling vet for tomorrow morning.\"]}],\"due\":[{\"what\":\"Wildlife Victoria travelling vet visit\",\"when\":\"Tomorrow morning\"}],\"check\":[\"What was the rescue date?\",\"Is there an RSPCA Queensland case or job number?\",\"Victorian rescue: which register should this go in?\"]}",
  "1u1kr9qx5s5": "{\"title\":\"Expert witness statement: Kelpie cross, 'Bluey'\",\"subtitle\":\"Case 26-1182 · Date of examination: 14 October 2026\",\"sections\":[{\"heading\":\"About me\",\"text\":\"My name is Dr Sam Lee. I hold a Bachelor of Veterinary Science with Honours (BVSc Hons). I am a registered veterinarian in Victoria, registration number [Registration number]. I have 12 years of experience in small animal and shelter practice.\",\"items\":[]},{\"heading\":\"Instructions\",\"text\":\"Inspector Kate Morris asked me to examine a dog seized from a property in Korumburra and to give my opinion on his health and welfare.\",\"items\":[]},{\"heading\":\"What I relied on\",\"text\":\"\",\"items\":[\"My physical examination of the dog on 14 October 2026 at 10.20 am.\",\"24 photographs of the dog taken on admission.\",\"Blood test results.\",\"Faecal flotation test result.\",\"The dog's weight gain over the six days after my examination, while on normal feeding.\"]},{\"heading\":\"The animal\",\"text\":\"\",\"items\":[\"Species and breed: dog, Kelpie cross\",\"Sex: male, entire (not desexed)\",\"Age: about four years, estimated from his teeth\",\"Colour: black and tan\",\"Microchip: 956000012345678\",\"Name: Bluey\"]},{\"heading\":\"Examination\",\"text\":\"I examined the dog on 14 October 2026 at 10.20 am at the clinic. Inspector Kate Morris was present. The dog was bright (alert and responsive). He weighed 14.2 kg. I assessed his body condition as 2 out of 9 on the Purina body condition scale (a 9-point scale where 1 is emaciated, 4 to 5 is ideal and 9 is obese). His ribs, spine and pelvis were easily seen, I could feel no fat over his body, and there was marked muscle loss over his head, spine and hindquarters. I estimated him to be about 7% dehydrated. His gums were tacky (sticky rather than moist) and he had a slow skin tent (skin that is slow to fall back into place when gently lifted). His coat was dull, with a heavy burden of fleas and flea dirt (flea droppings). Over the left hock (the ankle joint of the hind leg) there was an ulcerated wound (an open sore where the skin has been lost) measuring 4 cm by 3 cm, with granulation tissue (new pink tissue that forms as a wound begins to heal) at its edges. The wound was matted over with hair and faeces. His nails were overgrown and curling. When offered food he ate ravenously. He did not vomit.\",\"items\":[]},{\"heading\":\"Tests and treatment\",\"text\":\"\",\"items\":[\"Blood tests: mild anaemia (a low level of red blood cells), with a packed cell volume (PCV, the proportion of the blood made up of red cells) of 30%. Albumin (a protein in the blood) was low. All other results were normal.\",\"Faecal flotation (a test of a faeces sample for parasite eggs): positive for hookworm (an intestinal worm that feeds on blood).\",\"Response to feeding: on normal feeding, the dog gained 1.1 kg over six days.\"]},{\"heading\":\"Opinion\",\"text\":\"\",\"items\":[\"1. Body weight: For a dog of his frame I would expect a weight of 20 to 22 kg. At 14.2 kg he was about 6 to 8 kg below that. This, together with a body condition score of 2 out of 9, no fat I could feel and marked muscle loss, shows he was significantly underweight.\",\"2. Cause of weight loss: In my opinion the dog had been underfed. I found no medical cause for his weight loss: apart from mild anaemia and low albumin, his blood test results were normal. His gain of 1.1 kg in six days on normal feeding, and his eating ravenously when offered food, support underfeeding as the cause.\",\"3. Other explanations considered: The hookworm infection and heavy flea burden would have added to his anaemia. In my opinion they do not on their own explain his weight loss.\",\"4. Duration of underfeeding: In my opinion the dog had been underfed for at least four to six weeks, and probably longer. I base this on the degree of muscle loss over his head, spine and hindquarters.\",\"5. Age of the hock wound: In my opinion the wound over the left hock was at least seven to ten days old. I base this on the granulation tissue at its edges.\",\"6. Pain and suffering: In my opinion the dog would have been in pain from the hock wound and suffering from hunger.\",\"7. Whether the condition was obvious: In my opinion both the wound and his poor body condition would have been obvious to anyone looking at him. I base this on his ribs, spine and pelvis being easily seen and the size of the wound.\",\"8. Need for veterinary care: In my opinion the dog needed veterinary attention at least a week before he was seized.\"]},{\"heading\":\"Declaration\",\"text\":\"\",\"items\":[\"I understand my overriding duty is to help the court impartially on matters within my expertise, not to act as an advocate for any party.\",\"The opinions in this statement are wholly or substantially based on my specialised knowledge as a veterinarian.\",\"I have made all the inquiries I consider appropriate, and no matters of significance that I regard as relevant have, to my knowledge, been withheld.\",\"Signed: ____________________\",\"Date: ____________\"]}],\"due\":[],\"check\":[\"Veterinary registration number?\",\"Clinic name and address?\",\"Date the dog was seized?\",\"Albumin value and reference ranges?\",\"Treatment given for wound, fleas, hookworm?\"]}",
  "2bcz2y1j5x": "{\"animals\":[{\"patient\":{\"name\":\"Bluey\",\"species\":\"Canine\",\"breed\":\"Kelpie cross\",\"sex\":\"Male entire\",\"age\":\"Approximately 4 years (estimated by dentition)\",\"weight_kg\":\"14.2\",\"microchip\":\"956000012345678\",\"animal_id\":\"\",\"intake_type\":\"Inspectorate seizure\"},\"visit\":{\"type\":\"Inspectorate case exam\",\"clinician\":\"Dr Sam Lee BVSc (Hons)\"},\"subjective\":\"Expert statement for inspectorate case 26-1182. Examining veterinarian: Dr Sam Lee BVSc (Hons), registered veterinarian in Victoria, 12 years in small animal and shelter practice. Examination requested by Inspector Kate Morris. The dog was seized from a property in Korumburra. Examined on 14 October 2026 at 10:20 at the clinic, with Inspector Morris present. Black and tan coat.\",\"objective\":{\"vitals\":{\"temp_c\":\"\",\"hr_bpm\":\"\",\"rr_bpm\":\"\",\"bcs\":\"2/9 (Purina scale)\",\"mm_crt\":\"MM tacky\",\"hydration\":\"Approximately 7% dehydrated; slow skin tent\"},\"findings\":[\"Demeanour: bright. Ate avidly when offered food. No vomiting observed.\",\"Body weight 14.2 kg; expected weight for frame size estimated at 20-22 kg.\",\"BCS 2/9 (Purina scale): ribs, spine and pelvis easily visible; no palpable fat.\",\"Marked muscle loss over the head, spine and hindquarters.\",\"Mucous membranes tacky; skin tent slow.\",\"Coat dull, with a heavy flea burden and flea dirt present.\",\"Left hock: ulcerated wound measuring 4 x 3 cm, with granulation tissue at the wound edges. Wound covered by matted hair and faeces.\",\"Nails overgrown and curling.\",\"Haematology and biochemistry: PCV 30% (mild anaemia); albumin low; all other parameters within normal limits.\",\"Faecal flotation: positive for hookworm.\",\"Post-admission: weight gain of 1.1 kg recorded over six days on normal feeding.\"],\"photo_findings\":[]},\"assessment\":{\"problems\":[\"1. Emaciation (BCS 2/9) with marked muscle loss, consistent with underfeeding. Duration estimated at a minimum of 4-6 weeks, probably longer, based on the degree of muscle loss. No medical cause for the weight loss identified. Weight gain of 1.1 kg over six days on normal feeding is consistent with underfeeding.\",\"2. Ulcerated wound over the left hock (4 x 3 cm). Wound age estimated at a minimum of 7-10 days, based on granulation tissue.\",\"3. Dehydration, approximately 7%.\",\"4. Mild anaemia (PCV 30%) with hypoalbuminaemia. Flea burden and hookworm assessed as contributing to the anaemia, but not accounting for the weight loss on their own.\",\"5. Heavy flea infestation.\",\"6. Hookworm infection.\"],\"differentials\":[],\"prognosis\":\"\"},\"plan\":{\"procedures\":[\"24 photographs taken on admission.\"],\"diagnostics\":[],\"treatments\":[],\"hospital_plan\":[],\"home_care\":[],\"follow_up\":[]},\"welfare_notes\":\"In the examining veterinarian's assessment, the left hock wound would have caused pain, and the body condition is consistent with prolonged hunger. Both conditions would have been readily apparent on external visual inspection. In the examining veterinarian's assessment, veterinary attention was required at least one week before the date of seizure.\",\"check\":[]}]}",
  "y0co0i2a65": "{\"title\":\"Vet visit summary: Willow, juvenile wombat\",\"subtitle\":\"Juvenile female wombat, in care 5 weeks\",\"sections\":[{\"heading\":\"Text to your vet\",\"text\":\"Willow is a female juvenile wombat in care for 5 weeks after her mother was hit on the Inverloch road. She's on the prescribed mange treatment, last dose 10 days ago. Weight down from 6.2 to 6.0 kg over the past week. Eating fewer pellets but still grazing, loose droppings for 2 days, and scratching more again. Is the weight loss a concern, does she need another mange dose, and when can she move to the outdoor enclosure?\"},{\"heading\":\"Animal\",\"items\":[\"Species: wombat\",\"Sex: female\",\"Stage: juvenile\",\"Name: Willow\",\"Current weight: 6.0 kg\"]},{\"heading\":\"Reason for visit\",\"text\":\"Weight loss over the past week, reduced pellet intake, loose droppings and increased scratching while on mange treatment. Review of the mange treatment plan and readiness for the outdoor enclosure.\"},{\"heading\":\"History in care\",\"text\":\"Came into care 5 weeks ago after her mother was hit on the Inverloch road. Started on a vet-prescribed mange treatment while in care.\"},{\"heading\":\"Recent observations\",\"items\":[\"Weight: 6.2 kg dropping to 6.0 kg over the last week\",\"Feeding: eating fewer pellets, still grazing\",\"Toileting: loose droppings for the past 2 days\",\"Behaviour/skin: scratching more again\"]},{\"heading\":\"Current medications and treatment\",\"items\":[\"Mange treatment as prescribed by the vet; last dose 10 days ago\"]},{\"heading\":\"Questions for the vet\",\"items\":[\"Is a drop from 6.2 kg to 6.0 kg over one week a concern for her?\",\"Could the loose droppings and reduced pellet intake be linked to the weight loss?\",\"Does the increased scratching mean she needs another mange dose, and if so, when?\",\"When can she move to the outdoor enclosure?\"]},{\"heading\":\"What the carer needs back\",\"items\":[\"Written dosing instructions if another mange dose is needed\",\"A recheck date\",\"A decision on timing for the move to the outdoor enclosure\"]}],\"due\":[],\"check\":[\"What is the mange medication name and dose?\",\"How many mange doses has she had?\",\"What is the date of this visit?\",\"Is Inverloch the correct rescue location?\",\"What is her case or ID number?\"]}",
  "1x5dj5r70z": "```json\n{\"animal\":\"Adult female bare-nosed wombat\",\"species\":\"Common (bare-nosed) wombat (Vombatus ursinus)\",\"kind\":\"wildlife\",\"summary\":\"This adult female wombat (about 24 kg, pouch empty) was hit by a car on the Bass Highway near Kilcunda last night and has severe mange, crusted ears and a grazed left shoulder, but she is alert, hissing and walking well. The goal is to keep her calm, cool, safe and eating until the travelling vet sees her tomorrow morning, then help her recover fully and go home.\",\"photo_findings\":[],\n\"medications\":[],\n\"plan\":[{\"when\":\"Tonight\",\"tasks\":[\"Leave her settled in the quiet pen and check on her once from a distance before bed, without opening the hide box.\"]},{\"when\":\"Tomorrow morning\",\"tasks\":[\"Have her in the pen and the area clear and calm, ready for the travelling vet to examine her.\"]},{\"when\":\"After the vet visit\",\"tasks\":[\"Start any mange treatment or other care the vet prescribes, and keep her in strict quarantine for as long as the vet advises.\"]}],\n\"housing\":[\"Keep her in the quiet pen with the hide box, away from people, pets, traffic noise and the sight or smell of other animals.\",\"Keep the pen cool and shaded; wombats cope with cold much better than heat and overheat easily.\",\"Keep her in strict quarantine with her own buckets, bowls, tools and bedding, because mange mites spread to other animals and to people.\",\"Each day remove droppings and uneaten food, clean the bowls with a non-toxic disinfectant, and hot-wash and hot-dry any bedding, as mites can survive up to 21 days in cool, damp conditions.\"],\n\"feeding\":[\"Offer plenty of fresh native grasses, pulled with roots and soil attached, plus good grass hay, starting tonight.\",\"Wombaroo Kangaroo Pellets can be offered as a small extra alongside the grass and hay.\",\"Avoid carrots, bread, cereal or muesli mixes, chaff, clover, cabbage and any medicated cattle or chicken pellets, as these cause bloat or gum problems, or can be fatal.\",\"Keep fresh water available at all times in a heavy, shallow bowl she can't tip over.\"],\n\"activity\":[\"Handle her as little as possible: at about 24 kg she can bite, scratch and crush hands with her hard rump, so never reach into the hide box or corner her.\",\"Wear gloves and long, covered clothing whenever you go into the pen, and wash your hands well afterwards. Wombats can pass on mange, salmonella and ringworm even when the animal looks healthy.\",\"If you develop an itchy red rash, see your own doctor and mention mange.\"],\n\"care\":[\"Keep a written record of her exact rescue spot (the gravel pull-over on the south side of the Bass Highway, just east of the Kilcunda bridge), any treatments given, her weights and the outcome.\",\"Weigh her at least once a week, but only when it can be done safely and without a struggle.\"],\n\"daily_checks\":[\"Eating grass and hay\",\"Droppings normal\",\"Walking normally\",\"Shoulder graze clean\",\"Skin and ears improving\"],\"log_days\":7,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24000,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult wombat grazing on grass and hay, not fed a measured amount.\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Mange has cleared and her skin and ears have healed.\",\"The shoulder graze has fully healed and she walks and digs normally.\",\"She eats grass well and holds a healthy adult weight.\",\"A wildlife vet or experienced wombat rehabilitator has assessed her as physically and behaviourally fit.\"],\"target_weight\":\"About 24 kg or more, her healthy adult weight\",\"how\":[\"Release her in the evening or at night, when wombats are naturally active.\",\"Choose mild weather and never release in heat, storms or other harsh conditions.\",\"Move her in a secure, ventilated crate inside the car cabin, never the boot.\",\"Let her walk out of the crate on her own at the site.\"],\"where\":\"Release her as close as possible to the Kilcunda bridge rescue spot, in suitable habitat with shelter, food and water, set back from the highway rather than at the roadside pull-over.\"},\n\"escalate\":{\"vet\":[\"She stops eating, or eats very little for a day.\",\"The shoulder graze becomes red, swollen, smelly or starts to weep.\",\"She starts limping, or seems stiff or sore when moving.\",\"Diarrhoea lasts more than 24 hours.\"],\"urgent\":[\"Heat-stress signs: red feet, drooling onto her forelegs and chest, or lying on her back to expose her armpits and groin.\",\"Difficulty breathing, pale gums or collapse.\",\"Sudden weakness, wobbling, dragging her back legs, or a seizure.\",\"Any bleeding, or blood in her droppings or urine.\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Wildlife Victoria travelling vet, tomorrow morning\",\n\"sources\":[\"qld-cop-protected-animals-care\",\"qld-cop-protected-animals-release\",\"wires-wombats\",\"qld-gov-helping-injured-wildlife\",\"usyd-vet-emergency-signs\",\"qld-des-rescue-and-rehabilitation\"]}\n```",
  "1bpc1a9x2w8": "{\"title\":\"Short-term care plan: juvenile common brushtail possum\",\"subtitle\":\"Found this evening by Jenny\",\"sections\":[{\"heading\":\"Text to send\",\"text\":\"Hi Jenny, thanks for helping the young possum. Keep it in a secure box with a lid and air holes, lined with a towel, in a dark, quiet room. Keep your dog and children away. Fill the hot water bottle with warm (not hot) water, wrap it in a towel and put it at one end of the box so the possum can move away if it gets too warm. Handle it as little as possible. Food and water can wait for the rescuer. A rescuer will collect it tomorrow morning around 8am.\"},{\"heading\":\"Right now\",\"items\":[\"Move it to a sturdy box with a secure lid, air holes and a towel lining.\",\"Keep it in a warm, dark, quiet room.\",\"Handle it as little as possible.\",\"Keep your dog and children away.\"]},{\"heading\":\"Basic first aid\",\"items\":[\"Wrap the hot water bottle in a towel and place it at one end of the box. Refill it with warm water when it cools.\",\"Cover the box with a towel.\",\"Do not give food or water unless a vet, wildlife carer or RSPCA Queensland wildlife advises otherwise.\"]},{\"heading\":\"Getting it to a vet or shelter\",\"items\":[\"This is short-term care only.\",\"A rescuer will collect it tomorrow morning around 8am.\",\"Keep the box closed and in the quiet room until then.\"]},{\"heading\":\"Keep yourself safe\",\"items\":[\"Possums can scratch and bite. Use a thick towel and gloves if you must move it.\",\"Wash your hands after handling it or its bedding.\"]},{\"heading\":\"Call back straight away if\",\"items\":[\"It feels cold, goes floppy or breathes with effort.\",\"You see blood or an injury.\",\"Your dog or a cat touches it. It will need a vet the same day.\",\"RSPCA Queensland wildlife: 1300 ANIMAL (1300 264 625), 7am to 7pm. After hours, take it to the nearest vet.\"]},{\"heading\":\"Where it was found\",\"text\":\"On the ground in her backyard in Wonthaggi, under the big gum near the back fence.\"}],\"due\":[{\"what\":\"Rescuer collects the possum\",\"when\":\"Tomorrow morning around 8am\"}],\"check\":[\"Wonthaggi is in Victoria. Is the location correct?\",\"Should a Victorian contact number be given?\",\"Any cat contact or other possums nearby?\"]}",
  "15ieitbq0h9": "```json\n{\"animal\":\"Common ringtail possum joey, female, about 120 g, furred, eyes open\",\"species\":\"Common ringtail possum (Pseudocheirus peregrinus)\",\"kind\":\"wildlife\",\"summary\":\"This little female ringtail was caught by a cat in Wonthaggi yesterday; the vet checked her this morning, found no puncture wounds and started her on antibiotics. The goal is to grow her up and wean her onto native browse with other young ringtails, then soft-release her near where she was found.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Antibiotic dispensed by the vet (to prevent infection after the cat attack)\",\"how\":\"As dispensed by the clinic, following the label\",\"how_often\":\"Once a day\",\"how_long\":\"5 days, finishing the full course\",\"tip\":\"Give it at the same time each day and record each dose.\"}],\n\"plan\":[{\"when\":\"Days 1 to 5\",\"tasks\":[\"Give the antibiotic course.\"]},{\"when\":\"Day 5\",\"tasks\":[\"Last dose of the antibiotic.\"]},{\"when\":\"As she leaves the pouch and eats more leaves (from about 160 days old)\",\"tasks\":[\"Move her to a larger enclosure with branches and a nest box, ideally with other young ringtails.\",\"Slowly reduce milk as browse intake rises; she is usually fully weaned at about 310 g.\"]}],\n\"housing\":[\"Keep her in a fabric pouch inside a small, secure, ventilated enclosure in a quiet, dim room away from pets, noise and other species.\",\"Warm the pouch with a heat pad at about 30°C, as the vet advised, under only part of the enclosure so she can move away if too warm. Check this matches the app's pouch temperature for her stage.\",\"Remove droppings and uneaten food every day and wash food and water dishes daily with a non-toxic disinfectant.\",\"Ringtails are social, so she should be raised with other ringtail joeys through an experienced ringtail carer.\"],\n\"feeding\":[\"Feed Wombaroo Possum Milk Replacer >0.8 every 4 hours, as the vet advised. This is the right stage for a furred joey with open eyes; I'm not certain which stage was dispensed, so check with your vet. Use the feed calculator for the daily amount.\",\"Mix 25 g of powder (3½ scoops) with 80 mL of warm pre-boiled water to make 100 mL, warm to about 30°C, and never dilute or concentrate it. Never give cow's milk, as it gives possum joeys diarrhoea.\",\"After each feed, gently stroke her bottom with a warm, damp cloth until she wees and poos, and stop once she toilets on her own.\",\"Offer fresh native browse daily, such as young eucalypt leaves, with only the odd native flower as the vet suggested. Give no fruit, vegetables, cabbage-family plants, lantana, oleander or hydrangea, as these can cause bloat or poisoning.\",\"She will eat some of her own droppings, which is normal and keeps her gut healthy. Offer a shallow dish of water once she is eating leaves, with extra water between feeds in hot weather.\"],\n\"activity\":[\"Handle her only for feeds, toileting and weighing. Wear gloves and long sleeves, and wash your hands afterwards.\",\"Keep talking and cuddling to a minimum so she stays wild and does not become used to people.\",\"Add leafy branches to climb and hide in as she becomes more active.\"],\n\"care\":[\"Weigh her every day at the same time, before a feed, so the feed calculator stays accurate.\",\"Keep a record of her exact rescue location, weights, feeds, medication doses and outcome.\"],\n\"daily_checks\":[\"Weighed before feed\",\"Antibiotic given\",\"Feeds and toileting done\",\"Pouch warmth checked\",\"Fresh browse offered\"],\"log_days\":5,\n\"feed_calc\":{\"applies\":true,\"what\":\"Wombaroo Possum Milk Replacer >0.8\",\"weight_g\":120,\"stage\":\"Furred, eyes open, about 120 g (about 130 days)\",\"percent_body_weight_per_day\":14,\"feeds_per_day\":6,\"basis\":\"Wombaroo booklet common ringtail chart (about 17 mL a day at 120 g). Feeds are every 4 hours as the vet advised; the chart suggests 2 to 4 feeds a day at this stage.\",\"sure\":false},\n\"release\":{\"ready_when\":[\"Fully weaned and eating native browse on her own\",\"At a healthy weight of about 600 g, as the vet advised\",\"Wary of people and pets, and climbing and nesting normally\",\"Assessed as fit by a wildlife vet or experienced rehabilitator\"],\"target_weight\":\"About 600 g for this common ringtail possum (the vet's figure)\",\"how\":[\"Release her together with the ringtails she was raised with.\",\"Use a soft release: put a nest box at the site with browse and water.\",\"Release at dusk, in mild, dry weather.\",\"Keep topping up browse and water at the site for a while after release.\"],\"where\":\"Release near the rescue site in Wonthaggi if it has suitable trees, shelter and food and is away from roads and other hazards; otherwise use the nearest suitable habitat.\"},\n\"escalate\":{\"vet\":[\"She loses weight, or does not gain weight over 2 days\",\"Diarrhoea, or she refuses milk or browse\",\"Any swelling, wound, discharge or limping appears\",\"She is quiet, sleepy or not interested in feeds\"],\"urgent\":[\"She has trouble breathing, or is breathing with her mouth open\",\"Her belly is tight and swollen (bloat)\",\"She is cold, limp or collapsed (do not feed her; warm her slowly and go to the vet)\",\"Any bleeding\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"ringtail\",\n\"next_visit\":\"\",\"sources\":[\"qld-cop-protected-animals-care\",\"qld-cop-protected-animals-release\",\"wombaroo-milk-replacers-feeding-guide\",\"wires-possums\",\"qld-gov-helping-injured-wildlife\",\"qld-des-rescue-and-rehabilitation\"]}\n```",
  "1hlgwe88qq8": "{\"title\":\"Second Wildlife Ambulance Trailer and Wombat Mange Burrow-Flap Kit\",\"subtitle\":\"Bass Coast Shire Community Grants – Environment Stream\",\"sections\":[{\"heading\":\"Project summary\",\"text\":\"We are seeking $8,500 for a second wildlife ambulance trailer, a portable wombat burrow-flap kit with treatment supplies, and a volunteer training day. This will let us treat mange in wombats where they live instead of bringing every affected wombat into care, and strengthen our rescue capacity across the region. The project will run from February to December next year.\"},{\"heading\":\"About us\",\"text\":\"Bunurong Wildlife Care Inc is a registered charity and authorised wildlife shelter (Wildlife Shelter 15147751) based in Inverloch, Victoria. We rescue, rehabilitate and release native wildlife across Bass Coast and South Gippsland. Our work is carried out by 18 trained volunteers.\"},{\"heading\":\"The need\",\"text\":\"Last year we took in 214 animals, and about a third of them were wombats. Sixty of those wombats had mange. At present, every wombat with mange is brought into care for treatment. A portable burrow-flap kit would let us treat many of these wombats in the wild. A second ambulance trailer would increase our capacity to respond to rescues.\"},{\"heading\":\"What we will do\",\"items\":[\"Buy and fit out a second wildlife ambulance trailer.\",\"Buy a portable wombat burrow-flap kit and treatment supplies to treat mange in the wild.\",\"Run a volunteer training day.\",\"Treat wombats with mange at their burrows instead of bringing every one into care.\",\"Monitor treated wombats with trail cameras to track their recovery.\"]},{\"heading\":\"Budget\",\"items\":[\"Wildlife ambulance trailer: $5,200\",\"Burrow-flap kit and treatment supplies: $2,100\",\"Volunteer training day: $1,200\",\"Total requested: $8,500\"]},{\"heading\":\"Timeline\",\"items\":[\"February next year: project begins\",\"December next year: project ends\"]},{\"heading\":\"Outcomes and how we will measure them\",\"items\":[\"Number of wombats treated for mange in the wild.\",\"Number of treated wombats seen recovering on trail cameras.\"]},{\"heading\":\"Who benefits\",\"items\":[\"Wombats with mange, which can be treated in their own burrows.\",\"Native wildlife across Bass Coast and South Gippsland, through greater rescue capacity.\",\"Our volunteers, through additional training.\"]},{\"heading\":\"Partners and support\",\"text\":\"Wildlife Victoria and local vets already refer animals to us.\"},{\"heading\":\"Why us\",\"text\":\"We are an authorised wildlife shelter with 18 trained volunteers and a steady referral network that includes Wildlife Victoria and local vets. Last year we cared for 214 animals, many of them wombats, so we know the scale of mange in our area and we have the people and experience to deliver this project.\"}],\"due\":[{\"what\":\"Project start\",\"when\":\"February next year\"},{\"what\":\"Project end\",\"when\":\"December next year\"}],\"check\":[\"What is the grant application deadline?\",\"Which year does the project run?\",\"Do you already own trail cameras?\",\"How many wombats do you aim to treat?\",\"How many volunteers will attend the training day?\"]}",
  "21ima770g4d": "{\"animals\":[{\"patient\":{\"name\":\"\",\"species\":\"Wombat\",\"breed\":\"\",\"sex\":\"Female\",\"age\":\"Adult\",\"weight_kg\":\"24.3\",\"microchip\":\"\",\"animal_id\":\"\",\"intake_type\":\"\"},\n\"visit\":{\"type\":\"Clinical consult\",\"clinician\":\"\"},\n\"subjective\":\"Adult female wombat involved in a vehicle strike on the Bass Highway near Kilcunda last night. Presented by a carer this morning.\",\n\"objective\":{\"vitals\":{\"temp_c\":\"36.1\",\"hr_bpm\":\"82\",\"rr_bpm\":\"22\",\"bcs\":\"\",\"mm_crt\":\"MM pink, CRT <2 s\",\"hydration\":\"\"},\n\"findings\":[\"BAR, hissing on handling.\",\"Weight 24.3 kg.\",\"Sarcoptic mange affecting approximately 30% of the body surface, with crusting over both pinnae and both flanks.\",\"Early fissuring around the left eye.\",\"Abrasion over the left shoulder, 3 x 2 cm, superficial and contaminated.\",\"No fractures palpable. Ambulating normally.\",\"No neurological deficits detected.\",\"Pouch empty. Not lactating.\"],\n\"photo_findings\":[]},\n\"assessment\":{\"problems\":[\"1. Sarcoptic mange, moderate (approximately 30% of the body surface), with crusting of both flanks and both pinnae and early periocular fissuring on the left.\",\"2. Superficial contaminated abrasion over the left shoulder, 3 x 2 cm.\"],\n\"differentials\":[],\n\"prognosis\":\"Good\"},\n\"plan\":{\"procedures\":[\"Left shoulder abrasion cleaned with dilute chlorhexidine.\"],\n\"diagnostics\":[],\n\"treatments\":[{\"drug\":\"Cydectin (moxidectin) pour-on\",\"dose\":\"0.8 mL/kg (19.4 mL stated), per permit\",\"route\":\"Topical\",\"frequency\":\"Once\",\"duration\":\"\",\"when\":\"given\"},\n{\"drug\":\"Meloxicam (Metacam)\",\"dose\":\"0.2 mg/kg\",\"route\":\"SC\",\"frequency\":\"Once\",\"duration\":\"\",\"when\":\"given\"},\n{\"drug\":\"Cydectin (moxidectin) pour-on\",\"dose\":\"0.8 mL/kg, per permit\",\"route\":\"Topical\",\"frequency\":\"Weekly, given by carer\",\"duration\":\"15 weeks\",\"when\":\"continue\"}],\n\"hospital_plan\":[],\n\"home_care\":[\"House in a quiet pen with a hide box.\",\"Keep handling to a minimum.\",\"Weigh weekly.\"],\n\"follow_up\":[\"Recheck in 1 week.\"]},\n\"welfare_notes\":\"\",\n\"check\":[\"Carer authorised under the permit for weekly Cydectin?\",\"\\\"Side deck tin\\\" transcribed as Cydectin (moxidectin) pour-on: correct?\"]}]}",
  "38mmdz5m0g": "{\"title\":\"Wombat with mange recovering after being hit by car near Kilcunda\",\"subtitle\":\"Media statement, Inverloch\",\"sections\":[{\"heading\":\"Statement\",\"text\":\"An adult female wombat is being cared for by Bunurong Wildlife Care after she was hit by a car on the Bass Highway near Kilcunda last night. A wildlife carer brought her to us this morning.\\n\\nOur vet found no broken bones. She is walking normally and has a superficial graze on her left shoulder, which has been cleaned. She is alert and, as you would expect from a wild wombat, letting us know she would rather be left alone. She had no joey in her pouch.\\n\\nShe also has a moderate case of mange, a skin disease caused by tiny mites, covering about a third of her body, including her sides and both ears. She has started treatment, and her carer will continue it every week for 15 weeks. She will rest in a quiet pen with a hide box and be handled as little as possible. Her outlook is good.\\n\\nMange can make wombats weak and unwell, and sick wombats may be more likely to wander onto roads. Drivers can help by slowing down, and anyone who sees an injured wombat or one with signs of mange can help by reporting it.\"},{\"heading\":\"Quote\",\"text\":\"\\\"She's alert, walking normally and we found no broken bones, so her outlook is good. With weekly treatment for her mange over the coming months, she has a real chance of a full recovery.\\\" – [Name], [role], Bunurong Wildlife Care\"},{\"heading\":\"What the public can do\",\"items\":[\"Slow down on country roads, especially at dawn and dusk when wombats are most active.\",\"Do not approach an injured adult wombat. Keep a safe distance and call a local wildlife rescue group or vet.\",\"Note exactly where you saw the animal so rescuers can find it and return it home after treatment.\",\"If you see a wombat with signs of mange, such as crusty skin or hair loss, note the location and which parts of its body are affected.\"]},{\"heading\":\"About the organisation\",\"text\":\"Bunurong Wildlife Care is a registered wildlife shelter and charity in Inverloch, Victoria.\"},{\"heading\":\"Not for publication\",\"items\":[\"Do not name or identify the carer, or give their address, without consent.\",\"Leave out medication names and doses (moxidectin pour-on, meloxicam).\",\"Do not publish the eventual release site.\",\"Close-up details of the skin cracking around her left eye have been kept out as potentially distressing.\"]}],\"due\":[{\"what\":\"Vet recheck, possible media update\",\"when\":\"In 1 week\"},{\"what\":\"Weekly mange treatment and weigh-in by carer\",\"when\":\"Weekly for 15 weeks\"}],\"check\":[\"Who is the spokesperson, and their role?\",\"What was the date of the car strike?\",\"Who is the media contact, and their details?\",\"Was 'side deck tin' meant as Cydectin?\",\"OK to name Bass Highway near Kilcunda publicly?\"]}",
  "1bwc1swygmb": "{\"animals\":[{\"patient\":{\"name\":\"\",\"species\":\"Bare-nosed wombat\",\"breed\":\"\",\"sex\":\"Female\",\"age\":\"Adult\",\"weight_kg\":\"24.3\",\"microchip\":\"\",\"animal_id\":\"\",\"intake_type\":\"\"},\"visit\":{\"type\":\"Clinical consult\",\"clinician\":\"\"},\"subjective\":\"Re-presentation of a previously examined adult female wombat (same wombat). Plan dictated for discharge to carer. Presenting with moderate mange and a superficial graze on the left shoulder.\",\"objective\":{\"vitals\":{\"temp_c\":\"\",\"hr_bpm\":\"\",\"rr_bpm\":\"\",\"bcs\":\"\",\"mm_crt\":\"\",\"hydration\":\"\"},\"findings\":[\"Body weight 24.3 kg.\",\"Superficial graze over the left shoulder.\"],\"photo_findings\":[]},\"assessment\":{\"problems\":[\"1. Mange, moderate.\",\"2. Superficial graze, left shoulder.\"],\"differentials\":[],\"prognosis\":\"\"},\"plan\":{\"procedures\":[],\"diagnostics\":[],\"treatments\":[{\"drug\":\"Cydectin (moxidectin) pour-on\",\"dose\":\"\",\"route\":\"Topical, along the spine\",\"frequency\":\"Once\",\"duration\":\"\",\"when\":\"given\"},{\"drug\":\"Cydectin (moxidectin) pour-on\",\"dose\":\"19.4 mL\",\"route\":\"Topical, along the spine\",\"frequency\":\"Once weekly, same day each week\",\"duration\":\"15 weeks\",\"when\":\"continue\"},{\"drug\":\"Meloxicam (Metacam)\",\"dose\":\"\",\"route\":\"\",\"frequency\":\"Once\",\"duration\":\"\",\"when\":\"given\"}],\"hospital_plan\":[],\"home_care\":[\"Wear gloves when applying Cydectin pour-on.\",\"No meloxicam to be given at home.\",\"Clean the left shoulder graze once daily with saline.\",\"House in a quiet pen with a hide box and straw bedding.\",\"Minimal handling; no dogs nearby.\",\"Diet: grass hay, fresh native grasses and clean water; a few carrots are acceptable.\",\"Weigh weekly on the same scales.\"],\"follow_up\":[\"Recheck in 1 week.\",\"Contact vet if inappetent, if the graze becomes hot or malodorous, or if the periocular skin bleeds.\",\"Release at the Kilcunda pull-over once coat regrowth is evident and the skin has healed.\"]},\"welfare_notes\":\"\",\"check\":[\"Meloxicam dose and route given today?\",\"Cydectin volume applied today: 19.4 mL?\",\"Cydectin APVMA permit and carer authorisation current?\"]}]}",
  "1rv88r0wiio": "{\"animal\":\"Adult female bare-nosed wombat, 24.3 kg\",\"species\":\"Common (bare-nosed) wombat\",\"kind\":\"wildlife\",\"summary\":\"Thank you for caring for this wombat. She has moderate mange and a shallow graze on her left shoulder, and had her first Cydectin (moxidectin) pour-on and a meloxicam (Metacam) pain relief injection at the clinic today. The goal is to clear the mange, heal her skin and coat, and return her to the wild where she was found.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Cydectin pour-on (moxidectin, to kill the mange mites)\",\"how\":\"Pour 19.4 mL along her spine, wearing gloves and eye protection\",\"how_often\":\"Once a week, on the same day each week\",\"how_long\":\"15 weeks in total (today's clinic dose was the first)\",\"tip\":\"Keep it away from drains and water, as it is toxic to water insects. Off-label use needs an APVMA permit and authorisation; I'm not certain your paperwork covers this, so confirm with your vet.\"}],\n\"plan\":[{\"when\":\"In 1 week\",\"tasks\":[\"Recheck visit with the vet\"]},{\"when\":\"Week 15\",\"tasks\":[\"Last weekly Cydectin dose\"]}],\n\"housing\":[\"Keep her alone in a quiet pen with a hide box and straw bedding, well away from dogs and other animals in care, because mange spreads.\",\"Keep her cool and shaded; wombats overheat easily and handle cold far better than heat.\",\"Remove droppings and uneaten food daily, and clean food and water containers daily with a non-toxic disinfectant.\",\"Hot-wash and hot-dry any bedding or towels you reuse, as mites can survive in cool, damp conditions for up to 3 weeks.\"],\n\"feeding\":[\"Offer grass hay and fresh native grasses every day.\",\"A few carrots are fine as a treat for her.\",\"Do not give bread, cereal or medicated pellets such as cattle or chicken pellets; they can cause bloat or poisoning in wombats.\",\"Keep clean, fresh water available at all times.\"],\n\"activity\":[\"Handle her as little as possible; adult wombats stress easily, can bite and scratch, and can crush hands with their hard rump.\",\"Wear gloves and covered clothing whenever you touch her or her bedding, as mange gives people an itchy rash.\",\"Weigh her once a week on the same scales.\"],\n\"care\":[\"Clean the shoulder graze gently with saline once a day.\",\"Wash your hands well and use separate equipment for her, as wombats can carry salmonella and ringworm without showing signs.\",\"Record her weekly weights, each Cydectin dose and her exact rescue location in your register.\"],\n\"daily_checks\":[\"Eating hay and grass\",\"Graze clean and cool\",\"Skin around eyes\",\"Steady on her feet\",\"Droppings normal\"],\n\"log_days\":14,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24300,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult eating hay and grasses, not fed a measured amount\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Coat is growing back\",\"Skin, including the graze, has healed\",\"Eating well and holding her weight\",\"Assessed fit for release by a vet or experienced rehabilitator\"],\"target_weight\":\"\",\"how\":[\"Release her in the evening or at night, when wombats are naturally active.\",\"Avoid hot or stormy weather on release night.\",\"Transport her in a ventilated, covered crate in the car cabin, never the boot.\",\"Let her walk out of the crate in her own time.\"],\"where\":\"Release her back at the Kilcunda pull-over where she was found, provided it still has suitable habitat and is safe from hazards.\"},\n\"escalate\":{\"vet\":[\"She stops eating\",\"The graze becomes hot, swollen or smelly\",\"The skin around her eye bleeds\",\"She seems drowsy, wobbly, drooly or less responsive after a Cydectin dose\"],\"urgent\":[\"She collapses, can't stand or can't be roused\",\"Breathing is laboured or noisy\",\"Signs of heat stress: red feet, drooling onto her chest, or lying on her back\",\"Heavy bleeding or a sudden new wound\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Recheck with the vet in 1 week\",\n\"sources\":[\"qld-cop-protected-animals-care\",\"qld-cop-protected-animals-release\",\"rspca-qld-wildlife-hospital\",\"qld-des-rescue-and-rehabilitation\",\"qld-gov-helping-injured-wildlife\",\"wires-wombats\"]}",
  "14shj4exuyr": "{\"animal\":\"Adult female bare-nosed wombat\",\"species\":\"Common (bare-nosed) wombat\",\"kind\":\"wildlife\",\"summary\":\"Thank you for caring for this wombat, who was hit by a car near Kilcunda and also has moderate sarcoptic mange over about a third of her body, with a superficial graze on her left shoulder. She had pain relief, her graze cleaned and her first mange treatment at the clinic, and the goal is to clear her mange over 15 weeks and return her healthy to where she was found.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Cydectin pour-on (moxidectin) (treats mange)\",\"how\":\"Pour 19.4 mL along her back, as dispensed by the clinic. Wear gloves and eye protection, because it is a registered poison.\",\"how_often\":\"Once a week, on the same day each week\",\"how_long\":\"15 weeks in total (the first dose was given at the clinic today)\",\"tip\":\"Keep it out of drains, dams and creeks, as it is toxic to water insects.\"}],\n\"plan\":[{\"when\":\"In 1 week\",\"tasks\":[\"Vet recheck.\",\"Give the second Cydectin pour-on dose.\"]},{\"when\":\"Weeks 2 to 14\",\"tasks\":[\"Watch the crusting on her flanks, ears and around her left eye soften and fur regrow.\"]},{\"when\":\"Week 15\",\"tasks\":[\"Give the last Cydectin pour-on dose.\",\"Have her assessed as fit for release.\"]}],\n\"housing\":[\"Keep her in a quiet, secure pen with a hide box, well away from other animals in care, pets and household noise, because mange spreads easily.\",\"Keep the pen shaded and cool, as wombats overheat easily and handle cold far better than heat.\",\"Remove droppings and uneaten food every day and clean the food and water bowls daily with a non-toxic disinfectant.\",\"Hot-wash and hot-dry bedding and towels, as mange mites can survive up to 21 days in cool, damp material.\"],\n\"feeding\":[\"Offer plenty of fresh native grasses, ideally pulled up with roots and soil, plus grass hay.\",\"Keep a heavy, shallow bowl of fresh water available at all times.\",\"Feed no bread, cereal, muesli or carrots, as they cause gum infections and bloat, and carrots are used as rabbit bait.\",\"Never feed cattle, chicken or other medicated pellets, which can contain drugs that are fatal to wombats.\"],\n\"activity\":[\"Handle her as little as possible, because adult wombats stress easily in care.\",\"Never pull her out of her hide box or reach in after her, as she can crush a hand with her hard rump; she can also bite and scratch.\",\"Weigh her once a week, ideally by coaxing her into a crate on the scales rather than lifting her.\"],\n\"care\":[\"Wear gloves and covered clothing whenever you are near her and wash your hands afterwards, because mange causes an itchy rash in people and wombats can carry salmonella and ringworm.\",\"Judge her hydration from moist gums, bright eyes that are not sunken and a normal amount of urine; the skin pinch test does not work on wombat skin.\",\"Keep a record of her rescue location, each weekly weight, each Cydectin dose and her outcome.\"],\n\"daily_checks\":[\"Eating grass and hay\",\"Droppings and urine normal\",\"Shoulder graze clean\",\"Left eye not worse\",\"No signs of overheating\"],\n\"log_days\":14,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24300,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult wombat grazing on grass and hay, not fed a measured amount\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Crusting gone and fur regrowing on her flanks and ears, with a normal left eye\",\"Shoulder graze fully healed\",\"Weight held at or above her admission weight\",\"Eating well and behaving like a wild wombat\"],\"target_weight\":\"About 24 kg or more, which was her weight on arrival\",\"how\":[\"Release on a mild, dry evening around dusk, never in hot weather or storms.\",\"Move her in a ventilated crate inside the car cabin, never the boot.\",\"Open the crate near cover or burrows and let her leave in her own time.\",\"Dispose of her bedding by hot-washing it, or bin it in a sealed bag.\"],\"where\":\"Release her exactly where she was found near Kilcunda if the habitat is suitable, otherwise at the nearest suitable spot well away from the Bass Highway.\"},\n\"escalate\":{\"vet\":[\"Graze becomes red, swollen, smelly or weepy\",\"Not eating for more than a day\",\"Crusting spreads or her left eye gets worse\",\"Weight dropping from week to week\"],\"urgent\":[\"Wobbliness, drowsiness, drooling, slow responses or lying down after a Cydectin dose\",\"Signs of overheating: red feet, drooling onto her chest or forelegs, or lying on her back\",\"Laboured breathing or collapse\",\"Flies laying eggs or maggots in her wounds or crusts\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Recheck in 1 week\",\"sources\":[\"qld-cop-protected-animals-care\",\"qld-cop-protected-animals-release\",\"qld-des-rescue-and-rehabilitation\",\"qld-gov-helping-injured-wildlife\",\"wires-wombats\"]}",
  "xugwd42pi0": "```json\n{\"animal\":\"Adult female wombat\",\"species\":\"Common (bare-nosed) wombat\",\"kind\":\"wildlife\",\"summary\":\"This adult female wombat was hit by a car on the Bass Highway near Kilcunda. She has no broken bones but has moderate mange and a dirty graze on her left shoulder, which the clinic cleaned, and she had her first mange treatment and a pain-relief injection there. The goal is to clear her mange and heal her skin so she can go back to the wild.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Cydectin (moxidectin) pour-on (to treat mange)\",\"how\":\"Pour onto her skin at 0.8 mL per kg of body weight, about 19.4 mL at her current 24.3 kg, as shown by the clinic\",\"how_often\":\"Once a week\",\"how_long\":\"15 weeks\",\"tip\":\"Work out each dose from that week's weight. The note was checked against a handwritten entry, so I'm not completely certain of the product name; check with your vet if the label doesn't match.\"}],\n\"plan\":[{\"when\":\"Week 15\",\"tasks\":[\"Give the last weekly Cydectin dose.\",\"Once her skin has healed, have her assessed for release.\"]}],\n\"housing\":[\"Keep her in a quiet, secure pen with a hide box, well away from dogs, cats and household noise.\",\"Keep her away from other wombats, because mange spreads between them.\",\"Remove droppings and uneaten food every day, and clean her food and water bowls daily with a non-toxic disinfectant.\",\"Wear gloves when handling her or her bedding, and wash your hands afterwards.\"],\n\"feeding\":[\"Give a high-fibre diet of fresh native grasses (with roots and dirt still on) and grass hay.\",\"Keep fresh water available at all times in a heavy bowl she can't tip over.\",\"Don't give cattle or chicken pellets, because they can contain medicines that kill wombats.\",\"Don't give bread, cereal biscuits or muesli, because they cause gum infections and bloat.\",\"Avoid lucerne chaff, phalaris grass, clover, cabbage and carrots, because they can cause bloat or other problems.\"],\n\"activity\":[\"Handle her as little as possible, only for weighing and her weekly treatment, as she is a wild adult and can bite.\",\"Keep people contact to a minimum so she stays wild.\"],\n\"care\":[\"Weigh her once a week on treatment day, and record her weight, each dose and any changes.\",\"Look at her shoulder graze and the skin around her left eye each day for redness, swelling, pus or worsening cracks.\",\"Keep a record of exactly where she was found, so she can be returned there.\"],\n\"daily_checks\":[\"Eating and drinking\",\"Droppings normal\",\"Shoulder graze clean\",\"Left eye skin\",\"Pen cleaned\"],\"log_days\":14,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24300,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult wombat on grass and hay, so no measured milk feeds.\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Mange cleared, with her skin, ears and eye area healed.\",\"Shoulder graze fully healed.\",\"Weight steady at a normal adult weight and eating natural grasses well.\",\"Assessed as physically and behaviourally fit by a wildlife vet or experienced rehabilitator.\"],\"target_weight\":\"About 24 kg or more (her weight on arrival); I'm not certain of her ideal weight, so check with your vet.\",\"how\":[\"Release her at dusk or after dark, when wombats are normally active.\",\"Choose mild weather, never during storms or extreme heat.\",\"If possible, leave grass, hay, water and shelter at the site for a few nights to support her.\"],\"where\":\"Release her where she was found if the habitat is suitable. If that spot is too close to the highway, use the nearest safe habitat within her home range, and never a national park without approval.\"},\n\"escalate\":{\"vet\":[\"The graze becomes red, swollen, smelly or starts oozing pus.\",\"The cracking around her eye gets worse, or the eye becomes cloudy or runny.\",\"She stops eating for a day or her mange is clearly spreading.\",\"Diarrhoea, or no droppings for a day.\"],\"urgent\":[\"Collapse, weakness or wobbliness.\",\"Laboured or noisy breathing.\",\"Bleeding, or blood in her urine or droppings.\",\"Seizures.\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Recheck with the vet in 1 week.\",\"sources\":[\"qld-cop-protected-animals-care\",\"qld-cop-protected-animals-release\",\"qld-des-rescue-and-rehabilitation\",\"qld-gov-helping-injured-wildlife\",\"wires-wombats\",\"ava-vetvoice-post-surgery\",\"usyd-vet-emergency-signs\"]}\n```",
  "1bi0cap2b0v": "{\"polished\":\"Willow, juvenile wombat, F. Recheck.\\nWeight: 6.0 kg, down from 6.2 kg last week. BCS 4/9.\\nHistory: Eating pellets less, still grazing. Loose faeces for 2 days.\\nExam: BAR. T 35.8. Mange improving, with fur regrowth on both flanks. Pinnae still crusty.\\nFaecal float: negative.\\nPlan:\\nContinue moxidectin (Cydectin) pour-on weekly, 2 more doses.\\nAdd probiotic 1 sachet SID for 5 days.\\nReweigh in 3 days.\\nOK for outdoor enclosure once faeces are normal.\",\"animals\":[{\"patient\":{\"name\":\"Willow\",\"species\":\"Wombat\",\"breed\":\"\",\"sex\":\"Female\",\"age\":\"Juvenile\",\"weight_kg\":\"6.0\",\"microchip\":\"\",\"animal_id\":\"\",\"intake_type\":\"\"},\"visit\":{\"type\":\"Clinical consult\",\"clinician\":\"\"},\"subjective\":\"Presented for recheck. Weight 6.2 kg last week. Eating pellets less but still grazing. Loose faeces for 2 days.\",\"objective\":{\"vitals\":{\"temp_c\":\"35.8\",\"hr_bpm\":\"\",\"rr_bpm\":\"\",\"bcs\":\"4/9\",\"mm_crt\":\"\",\"hydration\":\"\"},\"findings\":[\"BAR.\",\"Body weight 6.0 kg, down from 6.2 kg last week.\",\"Skin: Mange improving, with fur regrowth on both flanks. Pinnae remain crusted.\",\"Faeces loose.\",\"Faecal flotation: negative.\"],\"photo_findings\":[]},\"assessment\":{\"problems\":[\"1. Mange, improving.\",\"2. Loose faeces, 2 days' duration (faecal flotation negative).\"],\"differentials\":[],\"prognosis\":\"\"},\"plan\":{\"procedures\":[],\"diagnostics\":[],\"treatments\":[{\"drug\":\"Moxidectin (Cydectin) pour-on\",\"dose\":\"\",\"route\":\"Topical\",\"frequency\":\"Weekly\",\"duration\":\"2 more doses\",\"when\":\"continue\"},{\"drug\":\"Probiotic (product not stated)\",\"dose\":\"1 sachet\",\"route\":\"PO (assumed)\",\"frequency\":\"SID\",\"duration\":\"5 days\",\"when\":\"continue\"}],\"hospital_plan\":[],\"home_care\":[],\"follow_up\":[\"Reweigh in 3 days.\",\"Outdoor enclosure permitted once faeces are normal.\"]},\"welfare_notes\":\"\",\"check\":[\"Moxidectin pour-on dose per kg?\",\"Probiotic route PO (assumed)?\"]}]}",
  "2ajmpfj51nc": "{\"title\":\"Wombat Hope returns to her burrow after nine weeks in care\",\"subtitle\":\"Media statement, Inverloch, Victoria\",\"sections\":[{\"heading\":\"Statement\",\"text\":\"A wombat hit on the Bass Highway near Kilcunda in August went back to her own burrow this morning after nine weeks in the care of Bunurong Wildlife Care.\\n\\nThe wombat, named Hope by her carers, came in with severe mange over most of her body and a graze on her shoulder. Over her time in care she had six weekly treatments for mange and put on 2 kilograms. She returned to her burrow with a full coat of fur.\\n\\nHope is one of 70 wombats Bunurong Wildlife Care has taken in so far this year. Many wildlife injuries happen on roads. Mange is a serious skin disease in wombats, and the right treatment makes a real difference.\\n\\nBunurong Wildlife Care is asking drivers to slow down on the Bass Highway at dawn and dusk, when wombats are on the move. The shelter is also asking anyone who sees a wombat with mange to report it rather than trying to treat it themselves.\"},{\"heading\":\"Quote\",\"text\":\"\\\"Watching her walk back into her own burrow, with a full coat of fur, is exactly why we do this,\\\" said Dr Sam Lee, senior veterinarian at Bunurong Wildlife Care.\"},{\"heading\":\"What the public can do\",\"items\":[\"Slow down on the Bass Highway at dawn and dusk, when wombats are most likely to be on the road.\",\"If you see a wombat with mange, report it to a local wildlife rescue group or vet rather than trying to treat it yourself. Note the exact location and where on its body the mange is.\",\"Do not approach an injured adult wombat. Keep your distance, call a local wildlife rescue group or vet, and wait for help.\",\"If you find a dead female wombat, a wildlife rescuer may need to check her pouch for a joey. Report it to a local wildlife rescue group or vet.\"]},{\"heading\":\"About the organisation\",\"text\":\"Bunurong Wildlife Care is a registered wildlife shelter and charity in Inverloch, Victoria.\"},{\"heading\":\"Not for publication\",\"items\":[\"Do not publish the exact location of Hope's burrow.\"]}],\"due\":[],\"check\":[\"What date was Hope released?\",\"Who is the media contact, with phone and email?\",\"Was Hope hit by a vehicle?\",\"Add Victoria's wildlife emergency number?\",\"Is the 70 wombats figure for this calendar year?\"]}",
  "19wx7xdg8na": "{\"animals\":[{\"patient\":{\"name\":\"Bluey\",\"species\":\"Canine\",\"breed\":\"Kelpie cross, black and tan\",\"sex\":\"Male entire\",\"age\":\"Approximately 4 years (estimated by dentition)\",\"weight_kg\":\"14.2\",\"microchip\":\"956000012345678\",\"animal_id\":\"\",\"intake_type\":\"Seized by inspectorate\"},\n\"visit\":{\"type\":\"Inspectorate case exam\",\"clinician\":\"Dr Sam Lee, BVSc (Hons)\"},\n\"subjective\":\"Expert statement for inspectorate case 26-1182. The examining veterinarian is Dr Sam Lee, BVSc (Hons), a registered veterinarian in Victoria with 12 years of small animal and shelter practice. Inspector Kate Morris requested examination of a dog seized from a property in Korumburra and an opinion on his health and welfare. The examination was conducted on 14 October 2026 at 10:20 at the clinic, with Inspector Morris present. Subsequent observation: the dog gained 1.1 kg over 6 days on normal feeding.\",\n\"objective\":{\"vitals\":{\"temp_c\":\"\",\"hr_bpm\":\"\",\"rr_bpm\":\"\",\"bcs\":\"2/9 (Purina scale)\",\"mm_crt\":\"MM tacky\",\"hydration\":\"Approximately 7% dehydrated (tacky MM, slow skin tent)\"},\n\"findings\":[\"Demeanour: Bright. Ate rapidly and readily when offered food. No vomiting observed.\",\"Body weight 14.2 kg. Expected weight for frame size is 20-22 kg.\",\"BCS 2/9 (Purina scale). Ribs, spine and pelvis are easily visible. No palpable fat.\",\"Marked muscle loss over the head, spine and hindquarters.\",\"Hydration: Approximately 7% dehydrated. Mucous membranes tacky and skin tent slow.\",\"Coat: Dull, with a heavy flea burden and flea dirt present.\",\"Left hock: Ulcerated wound measuring 4 x 3 cm, with granulation tissue at the wound edges. The wound is matted over with hair and faeces.\",\"Nails: Overgrown and curling.\",\"Haematology and biochemistry: Mild anaemia (PCV 30%). Albumin low. All other parameters normal.\",\"Faecal flotation: Positive for hookworm.\"],\n\"photo_findings\":[]},\n\"assessment\":{\"problems\":[\"1. Emaciation, BCS 2/9, with marked muscle loss. Body weight 14.2 kg against an expected 20-22 kg. No medical cause for the weight loss was identified. A weight gain of 1.1 kg over 6 days on normal feeding was assessed by the examining veterinarian as supporting inadequate food intake. Estimated duration of inadequate nutrition is at least 4-6 weeks, and probably longer, based on the degree of muscle loss.\",\"2. Ulcerated wound over the left hock, 4 x 3 cm. Estimated to be at least 7-10 days old based on the presence of granulation tissue.\",\"3. Dehydration, approximately 7%.\",\"4. Mild anaemia (PCV 30%). Hookworm and flea burden were assessed as contributing to the anaemia. They were assessed as not accounting for the weight loss on their own.\",\"5. Hypoalbuminaemia.\",\"6. Heavy flea infestation.\",\"7. Hookworm infection.\",\"8. Overgrown, curling nails.\"],\"differentials\":[],\"prognosis\":\"\"},\n\"plan\":{\"procedures\":[\"Twenty-four photographs taken on admission.\"],\"diagnostics\":[],\"treatments\":[],\"hospital_plan\":[],\"home_care\":[],\"follow_up\":[]},\n\"welfare_notes\":\"In the opinion of the examining veterinarian, the left hock wound would have caused pain, and the body condition is consistent with prolonged hunger. Both conditions would have been readily apparent on visual inspection of the dog. The examining veterinarian considered that veterinary attention was required at least one week before the date of seizure.\",\n\"check\":[]}]}",
  "20govb1d79h": "<polished>\nWillow, juvenile wombat, F. Recheck.\nWeight: 6.0 kg, down from 6.2 kg last week. BCS 4/9.\nHistory: Eating fewer pellets, still grazing. Loose faeces for 2 days.\nExam: BAR. T 35.8. Mange improving, with fur regrowth on both flanks. Pinnae still crusty.\nFaecal float: negative.\nPlan:\nContinue moxidectin (Cydectin) pour-on weekly, 2 more doses.\nAdd probiotic 1 sachet SID for 5 days.\nReweigh in 3 days.\nOK for outdoor enclosure once faeces are normal.\n</polished>\n{\"animals\":[{\"patient\":{\"name\":\"Willow\",\"species\":\"Wombat\",\"breed\":\"\",\"sex\":\"Female\",\"age\":\"Juvenile\",\"weight_kg\":\"6.0\",\"microchip\":\"\",\"animal_id\":\"\",\"intake_type\":\"\"},\"visit\":{\"type\":\"Clinical consult\",\"clinician\":\"\"},\"subjective\":\"Juvenile female wombat presented for a recheck during treatment for mange. She weighed 6.2 kg last week. She is eating fewer pellets but is still grazing. She has had loose faeces for 2 days.\",\"objective\":{\"vitals\":{\"temp_c\":\"35.8\",\"hr_bpm\":\"\",\"rr_bpm\":\"\",\"bcs\":\"4/9\",\"mm_crt\":\"\",\"hydration\":\"\"},\"findings\":[\"Demeanour: BAR.\",\"Body weight 6.0 kg, down from 6.2 kg last week.\",\"Skin: Fur regrowth present over both flanks.\",\"Pinnae: Crusting persists.\",\"Faecal float: Negative.\"],\"photo_findings\":[]},\"assessment\":{\"problems\":[\"1. Mange, improving. Fur regrowth over both flanks, and pinnal crusting persists.\",\"2. Loose faeces for 2 days. Faecal float negative.\",\"3. Weight loss of 0.2 kg over 1 week (6.2 kg to 6.0 kg), with reduced intake of pellets.\"],\"differentials\":[],\"prognosis\":\"\"},\"plan\":{\"procedures\":[],\"diagnostics\":[],\"treatments\":[{\"drug\":\"Moxidectin (Cydectin) pour-on\",\"dose\":\"\",\"route\":\"Topical\",\"frequency\":\"Weekly\",\"duration\":\"2 more doses\",\"when\":\"continue\"},{\"drug\":\"Probiotic\",\"dose\":\"1 sachet\",\"route\":\"\",\"frequency\":\"SID\",\"duration\":\"5 days\",\"when\":\"continue\"}],\"hospital_plan\":[],\"home_care\":[],\"follow_up\":[\"Reweigh in 3 days.\",\"Move to outdoor enclosure once faeces are normal.\"]},\"welfare_notes\":\"\",\"check\":[\"Moxidectin pour-on dose (mL/kg) not stated?\"]}]}",
  "1h8bdsvaxbo": "<polished>\nWillow, juvenile female wombat. Recheck.\nWeight: 6.0 kg (down from 6.2 kg last week). BCS 4/9.\nHistory: Eating fewer pellets but still grazing. Loose faeces for 2 days.\nExam: BAR. T 35.8 °C. Mange improving, with fur regrowth on both flanks. Pinnae still crusty.\nFaecal float: negative.\nPlan:\nContinue moxidectin pour-on weekly, 2 more doses.\nAdd probiotic 1 sachet SID for 5 days.\nReweigh in 3 days.\nOK for outdoor enclosure once faeces normal.\n</polished>\n{\"animals\":[{\"patient\":{\"name\":\"Willow\",\"species\":\"Wombat\",\"breed\":\"\",\"sex\":\"Female\",\"age\":\"Juvenile\",\"weight_kg\":\"6.0\",\"microchip\":\"\",\"animal_id\":\"\",\"intake_type\":\"\"},\n\"visit\":{\"type\":\"Clinical consult\",\"clinician\":\"\"},\n\"subjective\":\"Juvenile female wombat presented for recheck. Weight 6.2 kg last week. Eating fewer pellets but still grazing. Loose faeces for 2 days.\",\n\"objective\":{\"vitals\":{\"temp_c\":\"35.8\",\"hr_bpm\":\"\",\"rr_bpm\":\"\",\"bcs\":\"4/9\",\"mm_crt\":\"\",\"hydration\":\"\"},\"findings\":[\"BAR.\",\"Body weight 6.0 kg, down from 6.2 kg one week ago.\",\"BCS 4/9.\",\"Mange improving: fur regrowth present over both flanks.\",\"Pinnae remain crusted.\",\"Faecal flotation: negative.\"],\"photo_findings\":[]},\n\"assessment\":{\"problems\":[\"1. Mange, improving; pinnae still crusted.\",\"2. Loose faeces for 2 days; faecal flotation negative.\",\"3. Weight loss (6.2 kg to 6.0 kg over 1 week).\"],\"differentials\":[],\"prognosis\":\"\"},\n\"plan\":{\"procedures\":[],\"diagnostics\":[],\"treatments\":[{\"drug\":\"Moxidectin pour-on (Cydectin)\",\"dose\":\"\",\"route\":\"Topical (pour-on)\",\"frequency\":\"Weekly\",\"duration\":\"2 further doses\",\"when\":\"continue\"},{\"drug\":\"Probiotic (product not stated)\",\"dose\":\"1 sachet\",\"route\":\"\",\"frequency\":\"SID\",\"duration\":\"5 days\",\"when\":\"continue\"}],\"hospital_plan\":[],\"home_care\":[],\"follow_up\":[\"Reweigh in 3 days.\",\"Move to outdoor enclosure once faeces are normal.\"]},\n\"welfare_notes\":\"\",\n\"check\":[\"Moxidectin pour-on dose per kg?\"]}]}",
  "114cprgyd3o": "```json\n{\"animal\":\"Adult female wombat\",\"species\":\"Common (bare-nosed) wombat\",\"kind\":\"wildlife\",\"summary\":\"This adult female wombat was hit by a car on the Bass Highway near Kilcunda. She has no broken bones but has moderate mange and a small dirty graze on her left shoulder, and she had her first mange treatment and a pain relief injection at the clinic. The goal is to clear her mange, let her skin and graze heal, and return her to where she was found.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Cydectin (moxidectin) pour-on (to kill the mange mites)\",\"how\":\"Pour on the skin along her back, 0.8 mL for every kg of body weight (19.4 mL at her current 24.3 kg).\",\"how_often\":\"Once a week\",\"how_long\":\"15 weeks\",\"tip\":\"Wear gloves and pour slowly along her spine from shoulders to rump with as little handling as possible. Work out each dose from her latest weekly weight, and if you are unsure of the amount, ask your vet.\"}],\n\"plan\":[{\"when\":\"Day 7\",\"tasks\":[\"Give her first home dose of Cydectin, one week after the clinic dose.\",\"Take her to the vet for her recheck.\"]},{\"when\":\"Week 15\",\"tasks\":[\"Give her last dose of Cydectin.\"]},{\"when\":\"After she leaves\",\"tasks\":[\"Clean her pen and leave it empty for at least three weeks before another animal uses it.\"]}],\n\"housing\":[\"Keep her in a quiet pen with a hide box, away from people, pets and noise.\",\"House her apart from all other wildlife, and feed and clean her pen last, because mange spreads.\",\"Make sure the pen is dig-proof, with a concrete or buried-wire base, as wombats dig out.\",\"Wear gloves and protective clothing when handling her or her bedding, and wash your hands well afterwards, as people can catch mange.\"],\n\"feeding\":[\"Feed a high-fibre diet of fresh grasses (with roots and dirt still on) and grass hay, with Wombaroo Kangaroo Pellets as a supplement only.\",\"Never feed bread, cereal biscuits, muesli, carrots, chaff, fresh clover, cabbage or phalaris grass, as these cause bloat, gum infections or teach unsafe foods.\",\"Never give cattle or chicken pellets, as their added medicines can kill wombats.\",\"Give fresh water in a heavy dish every day.\"],\n\"activity\":[\"Handle her as little as possible, and only quickly and gently for treatment and weighing.\",\"She is a wild adult who hisses when handled, so do not try to tame her.\",\"Give her soil or deep substrate to dig in, and scatter her grasses so she can forage.\"],\n\"care\":[\"Weigh her once a week.\",\"Write down every Cydectin treatment with the date, amount and how she is going, and keep her record with the exact place she was found.\",\"In warm weather, keep flies off her graze and any scratched-off scab areas.\"],\n\"daily_checks\":[\"Eating and droppings\",\"Shoulder graze clean\",\"Left eye looks okay\",\"No flies on wounds\",\"Fresh water given\"],\n\"log_days\":7,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":null,\"stage\":\"\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult wombat eating grass and hay, not fed a measured milk amount.\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Scabs have fallen off and her skin, eye and shoulder have healed.\",\"She no longer needs any medical care.\",\"She is eating well and holding her weight.\",\"She is still wary of people, digging and using her hide.\"],\"target_weight\":\"\",\"how\":[\"Release within 24 hours of her being ready, and never in extreme weather.\",\"Release about an hour after dusk, ideally at an unoccupied burrow within about 150 m of where she was found.\",\"Open the box and let her leave in her own time.\",\"Tell Mange Management (mangemanagement.org.au) where she was released so any return of mange can be treated in the wild.\"],\"where\":\"Release her where she was found near Kilcunda, or if that spot is unsafe, at the closest suitable spot within her home range away from the highway, without crossing a boundary she would not normally cross.\"},\n\"escalate\":{\"vet\":[\"Her left eye looks worse, weepy, swollen or she keeps it shut.\",\"The shoulder graze becomes red, swollen, smelly or oozing.\",\"She stops eating for a day or is losing weight.\",\"Scabs are spreading or getting thicker despite treatment.\"],\"urgent\":[\"She collapses, is wobbly or cannot stand.\",\"She has trouble breathing.\",\"You see maggots on her or notice a rotting smell.\",\"New signs of injury from the car appear, such as bleeding, limping or a swollen belly.\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Recheck with the vet in 1 week.\",\n\"sources\":[\"vic-rehab-guidelines-wombats\",\"vic-cop-welfare-wildlife-rehabilitation\",\"vic-release-requirements\",\"vic-rehabilitator-authorisation-conditions\",\"vic-shelter-foster-carer-authorisation\",\"vic-mange-management\",\"vic-rehab-guidelines-part-a\",\"au-sarcoptic-mange-treatment-sheet\"]}\n```",
  "j2ua6e2aaa": "```json\n{\"animal\":\"Adult female wombat\",\"species\":\"Common (bare-nosed) wombat\",\"kind\":\"wildlife\",\"summary\":\"This adult female wombat was hit by a car last night and has moderate mange and a shallow graze on her left shoulder; at the clinic her graze was cleaned and she had a pain-relief injection and her first mange treatment. The goal is to clear her mange, heal the graze and return her to the wild as soon as she is fit.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Cydectin (moxidectin) pour-on (treats mange)\",\"how\":\"Pour onto her skin at 0.8 mL per kilogram of body weight (19.4 mL at her current 24.3 kg), as shown by the clinic\",\"how_often\":\"Once a week\",\"how_long\":\"15 weeks\",\"tip\":\"Work out each dose from her latest weekly weight, and only give it if you are authorised to do so under your permit.\"}],\n\"plan\":[{\"when\":\"Day 7\",\"tasks\":[\"Give your first weekly Cydectin dose (the clinic gave today's).\"]},{\"when\":\"Week 15\",\"tasks\":[\"Give the last Cydectin dose; the course then finishes.\"]}],\n\"housing\":[\"Keep her in a quiet pen with a hide box she can retreat into.\",\"Remove droppings and uneaten food every day, and clean the food and water bowls daily with a non-toxic disinfectant.\",\"Mange spreads, so keep her apart from other wombats and out of sight of other species.\",\"Keep her well away from pet cats and dogs.\"],\n\"feeding\":[\"Offer native grasses (roots and dirt included) and grass hay every day, as wombats need a high-fibre diet.\",\"Never give bread, cereal biscuits, muesli or carrots, as they cause gum infections and bloat.\",\"Never give medicated pellets such as cattle or chicken pellets, as they can be fatal to wombats.\",\"Keep fresh water available at all times.\"],\n\"activity\":[\"Handle her as little as possible, because stress slows recovery.\",\"She hisses and is strong, so move slowly, approach from the side and give her space.\",\"Wash your hands well after touching her or her bedding.\"],\n\"care\":[\"Look at the shoulder graze and the skin around her left eye each day without handling her if you can.\",\"Weigh her once a week and write down the weight, each Cydectin dose and anything unusual.\",\"Note exactly where she was found so she can go back to that spot.\"],\n\"daily_checks\":[\"Eating grass and hay\",\"Shoulder graze clean\",\"Left eye not worse\",\"Droppings look normal\",\"Fresh water filled\"],\"log_days\":14,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24300,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult wombat eating grass and hay, not a measured milk feed.\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Mange cleared and skin healed\",\"Shoulder graze fully healed\",\"Weight steady or rising and eating well\",\"A wildlife vet or experienced rehabilitator has assessed her as fit\"],\"target_weight\":\"About 24 kg or more (her weight now); I'm not certain of her ideal weight, check with your vet\",\"how\":[\"Release at dusk or after dark, when wombats are active.\",\"Never release in storms, extreme heat or very cold weather.\",\"A soft release, with hay, water and a shelter left at the site, is preferred.\"],\"where\":\"Release her where she was found if the habitat is suitable, otherwise as close as possible to it and away from the highway and other hazards, never in a national park without approval.\"},\n\"escalate\":{\"vet\":[\"The shoulder graze becomes red, swollen, smelly or oozing.\",\"The cracks around her left eye get worse, or the eye looks cloudy or stays closed.\",\"She stops eating for a day or loses weight between weekly weigh-ins.\",\"She develops diarrhoea.\"],\"urgent\":[\"She collapses, is very weak or can't walk.\",\"She has trouble breathing.\",\"Any bleeding that won't stop.\",\"Seizures or sudden wobbliness.\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Recheck with the vet in 1 week.\",\"sources\":[\"qld-cop-protected-animals-care\",\"qld-cop-protected-animals-release\",\"qld-des-rescue-and-rehabilitation\",\"qld-gov-helping-injured-wildlife\",\"wires-wombats\",\"ava-vetvoice-post-surgery\",\"usyd-vet-emergency-signs\"]}\n```",
  "psmqk6igze": "{\"animal\":\"Adult female bare-nosed wombat\",\"species\":\"Bare-nosed wombat (Vombatus ursinus)\",\"kind\":\"wildlife\",\"summary\":\"This adult female wombat was hit by a car on the Bass Highway near Kilcunda; she has no broken bones but has a grazed left shoulder and moderate mange over about a third of her body, and she had her first mange treatment and a pain relief injection at the clinic. The goal is to clear her mange, let the graze heal and return her to where she was found.\",\"photo_findings\":[],\n\"medications\":[{\"name\":\"Cydectin (moxidectin) pour-on (mange treatment)\",\"how\":\"Pour slowly along the middle of her back, 0.8 mL per kg of body weight (19.4 mL at her current 24.3 kg), wearing gloves\",\"how_often\":\"Once a week\",\"how_long\":\"15 weeks\",\"tip\":\"The clinic's handwritten note was hard to read and the vet's use of this product is under a permit, so I'm not certain of the product name: check the label is Cydectin before the first dose.\"}],\n\"plan\":[{\"when\":\"Day 7\",\"tasks\":[\"Give your first weekly Cydectin pour-on, on the day of her recheck.\"]},{\"when\":\"Week 15\",\"tasks\":[\"Give the last Cydectin dose.\"]}],\n\"housing\":[\"Keep her alone in a quiet pen with a hide box, away from other wildlife, and feed and clean her last because mange spreads.\",\"Make sure the pen has a concrete or buried-wire base so she can't dig out.\",\"Remove droppings and leftover food every day and change bedding often.\",\"After she leaves, clean the pen and leave it empty for at least three weeks before another animal uses it.\"],\n\"feeding\":[\"Offer plenty of fresh grass with roots and dirt still on, plus good grass hay, as wombats need a high-fibre diet.\",\"Never give bread, cereal biscuits, muesli, chaff, clover, cabbage or phalaris grass, as they cause bloat or gum problems.\",\"Never give cattle or chicken pellets, as their medicines can kill wombats.\",\"Give fresh water every day in a heavy dish she can't tip over.\"],\n\"activity\":[\"Handle her as little as possible; she is a wild adult and hissing means she is stressed.\",\"Approach slowly, never chase her, and keep pets and people away so she stays wild.\"],\n\"care\":[\"Wear gloves and long sleeves when handling her or her bedding, and wash your hands after, as people can catch mange.\",\"Weigh her once a week, ideally on treatment day, and use that weight for the dose.\",\"Record every treatment (date, product, amount, how she looked) along with her required admission records, and keep these for 3 years.\"],\n\"daily_checks\":[\"Eating and drinking\",\"Shoulder graze healing\",\"No flies on sores\",\"Droppings look normal\",\"Walking normally\"],\n\"log_days\":14,\n\"feed_calc\":{\"applies\":false,\"what\":\"\",\"weight_g\":24300,\"stage\":\"Adult\",\"percent_body_weight_per_day\":null,\"feeds_per_day\":null,\"basis\":\"Adult wombat eats grass and hay freely; no measured feeds.\",\"sure\":true},\n\"release\":{\"ready_when\":[\"Mange treatment finished and scabs gone, with fur growing back\",\"Shoulder graze fully healed and no more medical care needed\",\"Moving, seeing and hearing well\",\"Still wary of people and behaving like a wild wombat\"],\"target_weight\":\"About 24 kg or more (her admission weight)\",\"how\":[\"Release within 24 hours of her being ready, but not in extreme heat, cold or storms.\",\"Take her out about an hour after dusk.\",\"Ideally place her at an unoccupied burrow within about 150 m of where she was found.\",\"Open the box and let her leave in her own time.\"],\"where\":\"Release her where she was found near Kilcunda, or if that spot beside the highway isn't safe, at the closest suitable spot within her home range without crossing a barrier she wouldn't normally cross.\"},\n\"escalate\":{\"vet\":[\"Shoulder graze becomes red, swollen, smelly or oozing\",\"Cracks around her left eye get worse or the eye becomes weepy or closed\",\"Not eating for a day or more, or losing weight\",\"Scabs spreading or she seems very stressed in care\"],\"urgent\":[\"Flies laying eggs or maggots in her sores, or a rotting smell\",\"Collapse, wobbliness, dragging a leg or trouble breathing\",\"Bleeding that won't stop\"]},\n\"rehydration\":{\"needed\":false,\"weight_g\":null,\"dehydration_pct\":null,\"steps\":[]},\n\"species_group\":\"wombat\",\n\"next_visit\":\"Recheck with the vet in 1 week.\",\n\"sources\":[\"vic-rehab-guidelines-wombats\",\"vic-release-requirements\",\"vic-cop-welfare-wildlife-rehabilitation\",\"vic-rehabilitator-authorisation-conditions\",\"vic-shelter-foster-carer-authorisation\",\"vic-mange-management\",\"vic-rehab-guidelines-part-a\",\"au-sarcoptic-mange-treatment-sheet\"]}"
 }
};
